(function(){
'use strict';
const D=window.Lumi,$=s=>document.querySelector(s),S=()=>D.state;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',ticket:'M3 6h18v4a2 2 0 0 0 0 4v4H3v-4a2 2 0 0 0 0-4V6z M15 6v3m0 3v1m0 3v2',bag:'M5 7h14l1 14H4L5 7z M9 7V5a3 3 0 0 1 6 0v2',orders:'M6 3h12v18l-3-2-3 2-3-2-3 2V3z M9 7h6m-6 4h6m-6 4h4',scan:'M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5M7 12h10M9 8v8m6-8v8',box:'m3 7 9-4 9 4v10l-9 4-9-4V7z m0 0 9 4 9-4m-9 4v10M7 5l10 5',screen:'M3 4h18v12H3z M8 21h8m-4-5v5',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-2a8 8 0 0 1 16 0v2',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0m-2 4 6 6',arrow:'M5 12h14m-6-6 6 6-6 6',back:'M19 12H5m6-6-6 6 6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',plus:'M12 5v14M5 12h14',minus:'M5 12h14',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',alert:'m12 3 10 18H2L12 3z M12 9v5m0 3h.01',info:'M12 11v6m0-10h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',print:'M6 9V3h12v6M6 17H3V9h18v8h-3 M6 14h12v7H6z',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',logout:'M9 3H3v18h6m5-14 5 5-5 5m-6-5h13',refresh:'M20 7v-4m0 4h-4 M20 7a9 9 0 1 0 1 8',wallet:'M3 5h17v15H3z M3 5l14-3v3 M14 10h8v5h-8z',cash:'M2 5h20v14H2z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M5 8h1m12 8h1',card:'M2 5h20v14H2z M2 10h20 M5 15h4',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',help:'M9 8a3 3 0 0 1 6 0c0 3-3 2-3 5m0 4h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',bell:'M5 17h14l-2-3V8a5 5 0 0 0-10 0v6l-2 3z M10 21h4',external:'M14 3h7v7m0-7L10 14 M10 3H3v18h18v-7',seat:'M5 10V6a3 3 0 0 1 3-3h8a3 3 0 0 1 3 3v4 M3 10h3v6h12v-6h3v10H3z M6 20v2m12-2v2'};
const ic=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.info}"/></svg>`;
const btn=(label,action,cls='secondary',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const link=(label,path,cls='secondary')=>`<a class="btn ${cls}" href="#/${path}">${label}</a>`;
const badge=(label,tone='neutral')=>`<span class="badge ${tone}"><span class="dot"></span>${esc(label)}</span>`;
const empty=(title,text,action='')=>`<div class="empty">${ic('search')}<h3>${title}</h3><p>${text}</p>${action}</div>`;
const methodName={cash:'Tiền mặt',qr:'QR chuyển khoản',card:'Thẻ ngân hàng'};
const paymentName={paid:'Đã thanh toán',pending:'Chờ thanh toán',unknown:'Chưa rõ kết quả',failed:'Thất bại',expired:'Hết hạn',cancelled:'Đã hủy',success:'Thành công'};
const tone=s=>['paid','success','valid','Đang bán','delivered','open'].includes(s)?'success':['pending','unknown','held','waiting','ready'].includes(s)?'warning':['failed','expired','cancelled','used'].includes(s)?'danger':'neutral';
const seatNames={standard:'Thường',vip:'VIP',couple:'Ghế đôi',bed:'Giường',recliner:'Ghế ngả'};
const unit=l=>l.people===2?(l.seatType==='bed'?'/giường':'/cặp'):'/vé';
let route,view={day:0,query:'',format:'all',room:'all',hour:'all',foodGroup:'Tất cả',foodQuery:'',orderQuery:'',orderStatus:'all',orderMethod:'all',orderTime:'today',foodStatus:'ready',fulfillQuery:'',scanResult:null,paymentMethod:'cash',received:'',menu:false},toastTimer,modalCallback=null,lastFocus;
function toast(message,error=false){const t=$('#toast');t.className='toast '+(error?'error':'');t.innerHTML=ic(error?'alert':'check')+`<span>${esc(message)}</span>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='',5000);}
function dialog(title,html,onSubmit=null){lastFocus=document.activeElement;const m=$('#modal');m.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2>${btn(ic('close'),'close-modal','icon-btn','aria-label="Đóng hộp thoại"')}</div>${html}`;modalCallback=onSubmit;m.showModal();setTimeout(()=>m.querySelector('input,button')?.focus(),0);}
function closeDialog(){const m=$('#modal');if(m.open)m.close();modalCallback=null;lastFocus?.focus();}
function confirmAction(title,text,callback,label='Xác nhận'){dialog(title,`<p>${text}</p><div class="modal-actions">${btn('Quay lại','close-modal')}${btn(label,'modal-confirm','primary')}</div>`,callback);}
function currentRoute(){let [path,q='']=location.hash.replace(/^#\/?/,'').split('?');const bits=(path||'dashboard').split('/');return{page:bits[0],id:bits[1],params:new URLSearchParams(q)};}
function go(path){if(location.hash==='#/'+path)render();else location.hash='/'+path;}
function title(eyebrow,heading,sub,actions=''){return`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1 tabindex="-1">${heading}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
function panel(title,body,extra='',cls=''){return`<section class="panel ${cls}"><div class="panel-head"><h2>${title}</h2>${extra}</div>${body}</section>`;}
const navs=[['dashboard','Tổng quan ca','grid','01'],['sell','Bán vé tại quầy','ticket','F2'],['food','Quầy đồ ăn','bag','F3'],['orders','Đơn & giao dịch','orders','F4'],['scan','Soát vé','scan','F6'],['fulfillment','Giao sản phẩm','box',''],['rooms','Phòng & suất chiếu','screen',''],['shift','Ca làm việc','clock',''],['account','Tài khoản & hướng dẫn','help','']];
function shell(content){const s=S(),shiftLabel={pending:'Chưa nhận ca',open:'Ca đang mở',closed:'Đã kết ca'}[s.shift.status];
return`<div class="workspace ${view.menu?'menu-open':''}"><aside class="sidebar"><a class="brand" href="#/dashboard"><span class="brand-mark">L<span>•</span></span><span>lumi<span class="brand-small">CINEMA / STAFF</span></span></a>${btn(ic('close'),'toggle-menu','icon-btn mobile-only sidebar-close','aria-label="Đóng menu"')}<div class="workspace-tag"><span class="live-dot"></span> KHÔNG GIAN NHÂN VIÊN</div><div class="nav-group-label">VẬN HÀNH TẠI RẠP</div><nav aria-label="Điều hướng chính">${navs.filter(([p])=>D.can(p)).map(([p,label,i,key])=>`<a class="nav-link ${route.page===p||p==='sell'&&['checkout','receipt'].includes(route.page)?'active':''}" href="#/${p}">${ic(i)}<span>${label}</span>${key?`<kbd>${key}</kbd>`:''}${p==='fulfillment'?`<span class="nav-count">${s.orders.filter(o=>o.cinemaId===s.cinema.id&&o.payment==='paid'&&o.products.some(p=>p.delivered<p.qty)).length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="support-note">${ic('help')}<div><strong>Cần hỗ trợ vận hành?</strong><span>Liên hệ trưởng ca · Máy lẻ 102</span></div></div><div class="profile-mini"><span class="avatar">MA</span><div><strong>${esc(s.staff.name)}</strong><span>${s.staff.id} · ${s.role==='manager'?'Trưởng ca':s.role==='usher'?'Soát vé':'Nhân viên'}</span></div>${btn(ic('logout'),'logout','icon-btn','aria-label="Đăng xuất" title="Đăng xuất"')}</div></div></aside><div class="main-shell"><header class="topbar">${btn(ic('grid'),'toggle-menu','icon-btn mobile-only','aria-label="Mở hoặc đóng menu"')}<div class="location">${ic('screen')}<div><strong>${esc(s.cinema.name)}</strong><span>${esc(s.counter)}</span></div>${badge('Được phân công','success')}</div><div class="topbar-right"><div class="clock-box"><strong id="live-clock">${D.stamp(D.now())}</strong><span>${dateShort(D.now())} · TP.HCM</span></div><a class="shift-indicator ${s.shift.status}" href="#/shift"><span class="dot"></span>${shiftLabel}</a>${btn(ic('lock'),'lock','icon-btn','aria-label="Khóa màn hình" title="Khóa màn hình · Alt+L"')}</div></header><div class="demo-bar"><span>${ic('info')} <strong>BẢN MÔ PHỎNG</strong><span class="demo-description">Đăng nhập, giữ ghế, thanh toán & quét mã cục bộ.</span></span><label>Thử vai trò <select id="role-switch" aria-label="Chuyển vai trò mô phỏng">${Object.entries(D.roles).map(([k,r])=>`<option value="${k}" ${k===s.role?'selected':''}>${r.name}</option>`).join('')}</select></label></div><main id="main">${!D.storageOK?'<div class="notice danger">Trình duyệt không cho lưu localStorage. Dữ liệu chỉ được giữ đến khi tải lại trang.</div>':''}${content}</main><footer class="app-footer"><span>LUMI CINEMA <span class="muted">/</span> Vận hành gọn gàng. Trải nghiệm trọn vẹn.</span><span>Giờ mô phỏng tại rạp · UTC+7</span></footer></div></div>`;}
function dateShort(ms){return new Intl.DateTimeFormat('vi-VN',{timeZone:D.ZONE,day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(ms));}
function login(locked=false){return`<div class="login-layout"><section class="login-story"><a class="brand" href="#/dashboard"><span class="brand-mark">L<span>•</span></span><span>lumi<span class="brand-small">CINEMA / STAFF</span></span></a><div class="login-art"><div class="orbit-ring ring1"></div><div class="orbit-ring ring2"></div><span class="art-star">✦</span><div class="art-ticket">LUMI CINEMA<span>MỖI CA LÀM VIỆC<br>MỘT TRẢI NGHIỆM TỐT HƠN.</span><div class="ticket-dashes"></div><small>ĐỘI NGŨ VẬN HÀNH</small></div></div><h1>Phía sau mỗi<br>trải nghiệm điện ảnh.</h1><p>Mọi công cụ bạn cần để mang đến<br>một buổi xem phim trọn vẹn.</p><div class="login-foot">KHÔNG GIAN NHÂN VIÊN <span>© 2026 LUMI CINEMA</span></div></section><section class="login-form-wrap"><div class="login-card"><div class="eyebrow">${locked?'MÀN HÌNH ĐÃ KHÓA':'CHÀO MỪNG TRỞ LẠI'}</div><h2>${locked?'Tiếp tục ca làm việc':'Sẵn sàng cho ca mới?'}</h2><p>${locked?'Đơn và ghế của bạn vẫn được giữ theo thời gian còn lại.':'Đăng nhập để truy cập quầy làm việc được phân công.'}</p><div class="notice">${ic('info')}<span>Đây là đăng nhập mô phỏng. Không nhập mật khẩu thật.</span></div><form data-form="login"><label>Mã nhân viên<input name="employee" value="NV024" readonly autocomplete="username"></label><label>Mã truy cập minh họa <span class="label-note">Nhập bất kỳ, không lưu lại</span><input name="demoPassword" type="password" value="demo" required autocomplete="off"></label><div class="assignment"><span class="avatar">MA</span><div><strong>Nguyễn Minh Anh</strong><span>Lumi Nguyễn Trãi · Quầy vé 02</span><small>Bán vé, quầy đồ ăn, soát vé, trưởng ca</small></div></div><button class="btn primary full" type="submit">${locked?'Mở khóa':'Vào không gian làm việc'}${ic('arrow')}</button></form><div class="login-hint">${ic('lock')} Dữ liệu mẫu chỉ lưu trên trình duyệt này.<br>Không đồng bộ ghế giữa nhiều thiết bị.</div></div></section></div>`;}
function statCard(label,value,sub,icon){return `<div class="stat-card"><div><span>${label}</span><span class="stat-icon">${ic(icon)}</span></div><strong>${value}</strong><small>${sub}</small></div>`;}
function dashboard(){
 const s=S(),st=D.stats(),cashier=D.hasCashier();
 const upcoming=s.shows.filter(x=>x.start>D.now()&&dateShort(x.start)===dateShort(D.now())).sort((a,b)=>a.start-b.start).slice(0,4);
 const pending=s.orders.filter(o=>o.cinemaId===s.cinema.id&&['pending','unknown'].includes(o.payment));
 const cards=cashier?statCard('Giao dịch thành công',st.count,'Trong ca · tại quầy','orders')+statCard('Vé đã bán',st.ticketCount,'Tính theo số người','ticket')+statCard('Doanh thu vé',D.money(st.tickets),'Trước giảm giá','wallet')+statCard('Doanh thu đồ ăn',D.money(st.food),'Trước giảm giá','bag'):statCard('Khách đã check-in',s.tickets.filter(t=>t.cinemaId===s.cinema.id&&t.status==='used').reduce((n,t)=>n+t.people,0),'Trong phạm vi cụm rạp','scan')+statCard('Suất sắp chiếu',upcoming.length,'Các suất kế tiếp hôm nay','screen');
 const shows=upcoming.map(sh=>{const m=D.movie(sh.movieId),r=D.room(sh.roomId);return `<div class="upcoming-row"><div class="show-time"><strong>${D.stamp(sh.start)}</strong><small>${Math.floor((sh.start-D.now())/60000)} phút nữa</small></div><img class="poster-mini" src="assets/img/${m.art}.svg" alt=""><div class="upcoming-movie"><strong>${m.title}</strong><span>${r.name} · ${r.type} · ${r.format}</span></div><div class="upcoming-seats">${badge(D.showStatus(sh),tone(D.showStatus(sh)))}<span>${D.remaining(sh)} chỗ còn bán</span></div>${D.can('sell')&&D.showStatus(sh)==='Đang bán'?btn(ic('chevron'),'select-show','icon-btn',`data-id="${sh.id}" aria-label="Chọn suất ${m.title} ${D.stamp(sh.start)}"`):''}</div>`;}).join('');
 const payments=cashier?panel('Thanh toán trong ca',`<div class="payment-overview"><span>Tổng thu thực tế</span><strong>${D.money(st.revenue)}</strong><div class="payment-split"><span style="width:${st.revenue?st.cash/st.revenue*100:0}%"></span></div>${[['Tiền mặt',st.cash,'cash'],['Thẻ ngân hàng',st.card,'card'],['QR chuyển khoản',st.qr,'qr']].map(([l,n,k])=>`<div class="metric-row"><span><i class="legend-dot ${k}"></i>${l}</span><strong>${D.money(n)}</strong></div>`).join('')}<small>Chỉ tính giao dịch thành công tại quầy.<br>Giảm giá trong ca: ${D.money(st.discounts)}.</small></div>`):'';
 const tasks=(D.can('orders')?`<a class="task-row" href="#/orders"><span class="task-icon warning">${ic('alert')}</span><div><strong>${pending.length} đơn chờ kiểm tra</strong><span>Có kết quả chưa xác định</span></div>${ic('chevron')}</a>`:'')+(D.can('fulfillment')?`<a class="task-row" href="#/fulfillment"><span class="task-icon peach">${ic('bag')}</span><div><strong>${s.orders.filter(o=>o.cinemaId===s.cinema.id&&o.payment==='paid'&&o.products.some(p=>p.delivered<p.qty)).length} đơn đồ ăn chưa giao xong</strong><span>Kiểm tra trước khi bàn giao</span></div>${ic('chevron')}</a>`:'')+(D.can('rooms')?`<a class="task-row" href="#/rooms"><span class="task-icon mint">${ic('screen')}</span><div><strong>Lưu ý vận hành phòng 04</strong><span>Kiểm tra điều hòa trước suất</span></div>${ic('chevron')}</a>`:'');
 return title('KHÔNG GIAN LÀM VIỆC','Một ca làm việc thật suôn sẻ.',`Xin chào Minh Anh. Đây là tình hình tại ${esc(s.cinema.name)}.`,D.can('sell')?link(ic('plus')+' Bán vé mới','sell','primary'):D.can('scan')?link(ic('scan')+' Bắt đầu soát vé','scan','primary'):'')+(s.shift.status!=='open'?`<div class="notice warning shift-callout">${ic('clock')}<div><strong>${s.shift.status==='closed'?'Ca đã kết thúc':'Bạn chưa nhận ca'}</strong><span>Đến Ca làm việc để xem biên bản hoặc nhận ca.</span></div>${link('Đến ca làm việc '+ic('arrow'),'shift','primary small')}</div>`:'')+`<div class="stats-grid">${cards}</div><div class="dashboard-grid"><div>${panel('Suất chiếu sắp bắt đầu',`<div class="upcoming-list">${shows}</div>`,D.can('rooms')?link('Xem lịch '+ic('arrow'),'rooms','text-btn'):'')}${cashier?panel('Giao dịch gần đây',transactionsTable(s.transactions.filter(t=>D.order(t.orderId)?.source==='counter').slice(-4).reverse()),link('Tất cả giao dịch','orders','text-btn')):panel('Thông tin cần nhớ','<div class="padded"><p>Kiểm tra riêng từng vé và số người tương ứng. Vé đã vào rạp không được xác nhận lần nữa.</p><p>Chuyển khách về quầy khi vé sai rạp hoặc chưa thanh toán.</p></div>')}</div><div>${payments}${panel('Cần xử lý',`<div class="task-list">${tasks}</div>`)}<div class="shortcut-card"><span class="eyebrow">LÀM VIỆC NHANH HƠN</span><h3>Ít thao tác.<br>Nhiều trải nghiệm tốt.</h3><p><kbd>F2</kbd> Bán vé <kbd>F4</kbd> Tra cứu đơn</p><a href="#/account">Xem tất cả phím tắt ${ic('arrow')}</a></div></div></div>`;
}
function weekday(ms){return new Intl.DateTimeFormat('vi-VN',{timeZone:D.ZONE,weekday:'long'}).format(ms);}
function sale(){const step=route.params.get('step')||'shows';return title('BÁN HÀNG TẠI QUẦY','Bán vé','Chọn suất, chọn chỗ ngồi và hoàn tất đơn hàng.',badge('Quầy vé 02'))+`<div class="sale-layout"><section class="sale-services"><nav class="sale-tabs" aria-label="Các bước bán vé">${[['shows','1','Chọn suất'],['seats','2','Chọn ghế'],['food','3','Thêm đồ ăn']].map(([k,n,l])=>`<a class="${k===step?'active':''}" href="#/sell?step=${k}"><span>${n}</span>${l}</a>`).join('')}</nav>${step==='shows'?showPicker():step==='seats'?seatPicker():foodCatalog(true)}</section>${cart()}</div>`;}
function showPicker(){
 const s=S(),shows=s.shows.filter(x=>dateShort(x.start)===dateShort(s.clockBase+view.day*86400000)&&D.movie(x.movieId).title.toLowerCase().includes(view.query.toLowerCase())&&(view.format==='all'||D.room(x.roomId).format===view.format)&&(view.room==='all'||x.roomId===view.room)&&(view.hour==='all'||Number(new Intl.DateTimeFormat('en-GB',{timeZone:D.ZONE,hour:'2-digit',hourCycle:'h23'}).format(x.start))>=(view.hour==='afternoon'?12:17)));
 return `<div class="show-picker"><div class="picker-toolbar"><label class="search-field">${ic('search')}<input id="movie-search" data-filter="query" value="${esc(view.query)}" aria-label="Tìm tên phim" placeholder="Tìm tên phim…"><kbd>/</kbd></label><div class="date-tabs">${[0,1,2].map(d=>btn(`<strong>${d===0?'Hôm nay':d===1?'Ngày mai':weekday(s.clockBase+d*86400000)}</strong><span>${dateShort(s.clockBase+d*86400000).slice(0,5)}</span>`,'sale-day',d===view.day?'active':'',`data-day="${d}" aria-pressed="${d===view.day}"`)).join('')}</div></div><div class="filter-row"><label>Định dạng<select data-filter="format"><option value="all">Tất cả định dạng</option>${['2D','3D'].map(x=>`<option ${view.format===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Phòng chiếu<select data-filter="room"><option value="all">Tất cả phòng</option>${D.roomDefs.map(r=>`<option value="${r.id}" ${view.room===r.id?'selected':''}>${r.name} · ${r.type}</option>`).join('')}</select></label><label>Khung giờ<select data-filter="hour"><option value="all">Tất cả khung giờ</option><option value="afternoon" ${view.hour==='afternoon'?'selected':''}>Từ 12:00</option><option value="evening" ${view.hour==='evening'?'selected':''}>Từ 17:00</option></select></label>${btn('Xóa lọc','clear-show-filters','text-btn')}</div><div class="section-label">${shows.length} SUẤT CHIẾU <span>· ${dateShort(s.clockBase+view.day*86400000)}</span></div><div class="movie-list">${D.movies.filter(m=>shows.some(sh=>sh.movieId===m.id)).map(m=>`<article class="movie-row"><img class="movie-poster" src="assets/img/${m.art}.svg" alt="Áp phích minh họa ${m.title}"><div class="movie-info"><div class="movie-title"><span class="age age-${m.age}">${m.age}</span><h2>${m.title}</h2></div><p>${m.genre} · ${m.duration} phút</p><div class="show-options">${shows.filter(sh=>sh.movieId===m.id).sort((a,b)=>a.start-b.start).map(sh=>{const r=D.room(sh.roomId),status=D.showStatus(sh);return `<button type="button" class="show-option ${status==='Đang bán'?'':'unavailable'}" data-action="select-show" data-id="${sh.id}" ${status==='Đang bán'?'':'disabled'}><div><strong>${D.stamp(sh.start)}</strong><span>– ${D.stamp(sh.start+m.duration*60000)}</span></div><span>${r.format} · ${r.lang}</span><span>${r.name} · ${r.type}</span><small>${status==='Đang bán'?D.remaining(sh)+' chỗ còn bán':status}</small></button>`;}).join('')}</div></div></article>`).join('')||empty('Không có suất phù hợp','Thử ngày hoặc bộ lọc khác.',btn('Xóa bộ lọc','clear-show-filters','primary'))}</div><div class="subtle-note">${ic('info')} Giá vé hiển thị theo suất, hạng ghế và đối tượng khi chọn ghế.</div></div>`;
}
function holdText(){const d=S().draft;if(!d.holdUntil)return '05:00 khi chọn ghế';const n=Math.max(0,Math.ceil((d.holdUntil-D.now())/1000));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function seatPicker(){
 const d=S().draft,sh=D.show(d.showId);if(!sh)return empty('Chọn một suất chiếu trước','Sơ đồ ghế và giá được tải theo đúng phòng.',link('Chọn suất chiếu','sell','primary'));
 const m=D.movie(sh.movieId),r=D.room(sh.roomId),all=D.seats(sh);
 return `<div class="seat-picker"><div class="selected-show"><div><span class="eyebrow">SUẤT ĐANG CHỌN</span><h2>${m.title} <span class="age">${m.age}</span></h2><p>${D.stamp(sh.start,true)} · ${r.name} · ${r.type} · ${r.format} · ${r.lang}</p></div>${link('Đổi suất','sell','text-btn')}</div><div class="hold-strip">${ic('clock')}<span>Giữ ghế cục bộ <strong id="hold-countdown">${holdText()}</strong></span>${btn('Thử hết giờ','expire-hold','text-btn')}</div><div class="screen-label"><div></div>MÀN HÌNH</div><div class="seat-map-scroll"><div class="seat-map">${[...new Set(all.map(x=>x.row))].map(row=>{const list=all.filter(x=>x.row===row);return `<div class="seat-row"><span class="row-label">${row}</span>${list.map((seat,i)=>{const selected=d.seats.some(l=>l.seat===seat.id),status=D.seatStatus(sh,seat.id);return `<button type="button" class="seat ${seat.type} ${selected?'selected':status} ${i===Math.floor(list.length/2)?'aisle':''}" data-action="seat" data-seat="${seat.id}" aria-label="Ghế ${seat.id}, ${seatNames[seat.type]}, ${selected?'đang chọn':{free:'trống',sold:'đã bán',held:'đang giữ',disabled:'không sử dụng'}[status]}, ${D.money(D.fare(sh,seat))}, ${seat.people} người" aria-pressed="${selected}" ${!selected&&status!=='free'?'disabled':''}><span>${!selected&&status==='sold'?'×':seat.id}</span>${seat.people===2?'<small>2 người</small>':''}</button>`;}).join('')}<span class="row-label">${row}</span></div>`;}).join('')}</div></div><div class="seat-legend">${[['free','Trống'],['selected','Đang chọn'],['held','Đang giữ'],['sold','Đã bán'],['disabled','Không sử dụng']].map(([k,l])=>`<span><i class="seat-swatch ${k}"></i>${l}</span>`).join('')}</div><div class="fare-guide">${[...new Set(all.map(x=>x.type))].map(t=>{const seat=all.find(x=>x.type===t);return `<span><i class="type-swatch ${t}"></i>${seatNames[t]} <strong>${D.money(D.fare(sh,seat))}${seat.people===2?t==='bed'?'/giường':'/cặp':'/vé'}</strong></span>`;}).join('')}</div>${d.seats.length?`<div class="selected-seat-list"><div class="section-label">ĐỐI TƯỢNG VÉ <span>· GIÁ CUỐI CÙNG</span></div>${d.seats.map(l=>`<div class="selected-seat-line"><span class="seat-chip">${l.seat}</span><div><strong>${seatNames[l.seatType]}</strong><small>${l.people} người</small></div><label class="sr-only" for="type-${l.seat}">Đối tượng vé ghế ${l.seat}</label><select id="type-${l.seat}" data-seat-type="${l.seat}">${D.availableTypes(sh,all.find(x=>x.id===l.seat)).map(t=>`<option value="${t}" ${l.type===t?'selected':''}>${D.audience[t]}</option>`).join('')}</select><strong>${D.money(l.price)}<small>${unit(l)}</small></strong>${btn(ic('close'),'seat','icon-btn',`data-seat="${l.seat}" aria-label="Bỏ ghế ${l.seat}"`)}</div>`).join('')}${d.seats.some(l=>l.type!=='adult')?`<div class="notice warning compact">${ic('info')} Kiểm tra giấy tờ khi bán vé ưu tiên.</div>`:''}</div>`:''}<div class="subtle-note">${ic('info')} Giữ ghế chỉ trên trình duyệt này, không đồng bộ giữa nhiều thiết bị.</div></div>`;
}
function foodCatalog(embedded=false){const items=D.products.filter(p=>(view.foodGroup==='Tất cả'||p.group===view.foodGroup)&&p.name.toLowerCase().includes(view.foodQuery.toLowerCase()));return `<div class="food-catalog"><div class="food-toolbar"><label class="search-field">${ic('search')}<input id="food-search" data-filter="foodQuery" value="${esc(view.foodQuery)}" aria-label="Tìm sản phẩm" placeholder="Tìm sản phẩm, combo…"></label>${embedded?'':btn('Đơn đồ ăn mới','new-food','secondary small')}</div><div class="category-tabs">${['Tất cả','Combo','Bắp rang','Đồ uống','Ăn nhẹ'].map(g=>btn(g,'food-group',view.foodGroup===g?'active':'',`data-group="${g}" aria-pressed="${view.foodGroup===g}"`)).join('')}</div><div class="product-grid">${items.map(p=>`<article class="product-card ${p.available?'':'out-of-stock'}"><div class="product-image"><img src="assets/img/${p.image}.svg" alt="Minh họa ${p.name}">${!p.available?badge('Hết hàng','danger'):p.group==='Combo'?badge('Combo'):''}</div><div class="product-body"><h3>${p.name}</h3><p>${p.description}</p><strong>${D.money(p.price)}<small>/phần</small></strong><label class="sr-only" for="option-${p.id}">Tùy chọn ${p.name}</label><select id="option-${p.id}" ${p.available?'':'disabled'}>${p.options.map(o=>`<option>${o}</option>`).join('')}</select>${btn(ic('plus')+' Thêm vào đơn','add-product','secondary full',`data-id="${p.id}" ${p.available?'':'disabled'}`)}</div></article>`).join('')||empty('Không tìm thấy sản phẩm','Thử một tên khác.')}</div><div class="subtle-note">${ic('info')} Chỉ hiển thị trạng thái còn bán/hết hàng, không giả lập tồn kho.</div></div>`;}
function foodPage(){return title('BÁN HÀNG TẠI QUẦY','Quầy đồ ăn','Bán riêng sản phẩm hoặc thêm vào đơn vé hiện tại.')+`<div class="sale-layout"><section class="panel">${foodCatalog()}</section>${cart()}</div>`;}
const mask=p=>p?p.slice(0,3)+' ••• '+p.slice(-3):'Không cung cấp';
function cart(){
 const d=S().draft,t=D.draftTotals(),sh=D.show(d.showId),m=sh&&D.movie(sh.movieId),r=sh&&D.room(sh.roomId),has=d.seats.length||d.products.length;
 return `<aside class="cart panel"><div class="cart-heading"><span class="cart-icon">${ic('orders')}</span><div><h2>Đơn hiện tại</h2><span>${d.paymentOrder||'Chưa ghi nhận giao dịch'}</span></div>${has&&!d.paymentOrder?btn(ic('refresh'),'clear-cart','icon-btn','aria-label="Xóa đơn hiện tại"'):''}</div><div class="cart-scroll">${m?`<div class="cart-movie"><img src="assets/img/${m.art}.svg" alt=""><div><h3>${m.title}</h3><span>${S().cinema.name} · ${r.name}</span><strong>${D.stamp(sh.start,true)}</strong><span>${r.format} · ${r.type} · ${r.lang}</span></div></div>`:''}${d.seats.length?`<div class="cart-section-label">VÉ XEM PHIM <span>${d.seats.reduce((n,l)=>n+l.people,0)} người</span></div>${d.seats.map(l=>`<div class="cart-ticket"><span class="seat-chip">${l.seat}</span><div><strong>${seatNames[l.seatType]}</strong><small>${D.audience[l.type]} · ${l.people} người</small></div><strong>${D.money(l.price)}<small>${unit(l)}</small></strong></div>`).join('')}`:''}${d.products.length?`<div class="cart-section-label">ĐỒ ĂN & THỨC UỐNG</div>${d.products.map(p=>`<div class="cart-product"><div><strong>${D.products.find(x=>x.id===p.id).name}</strong><small>${p.option}</small><span class="qty-control">${btn('−','product-qty','',`data-key="${p.key}" data-delta="-1" aria-label="Giảm số lượng"`)}<b>${p.qty}</b>${btn('+','product-qty','',`data-key="${p.key}" data-delta="1" aria-label="Tăng số lượng"`)}</span></div><strong>${D.money(p.price*p.qty)}</strong></div>`).join('')}`:''}${!has?`<div class="cart-empty">${ic('ticket')}<h3>Chờ một trải nghiệm mới</h3><p>Chọn suất và ghế hoặc thêm<br>đồ ăn để bắt đầu đơn hàng.</p></div>`:`<div class="customer-box">${ic('user')}<div><strong>${d.customer?esc(d.customer.name):'Khách vãng lai'}</strong><span>${d.customer?'Thành viên · '+mask(d.customer.phone):'Có thể bán không cần thành viên'}</span></div>${btn(d.customer?'Đổi':'Tìm','customer','text-btn')}</div><div class="promo-row"><label class="sr-only" for="promo-input">Mã ưu đãi</label><input id="promo-input" placeholder="Mã ưu đãi" value="${esc(d.promo)}" ${d.paymentOrder?'disabled':''}>${btn(d.promo?'Bỏ mã':'Áp dụng',d.promo?'remove-promo':'promo','text-btn',d.paymentOrder?'disabled':'')}</div><p class="micro">${t.promoInvalid?'Mã không còn đủ điều kiện. Bỏ mã hoặc bổ sung đơn đến 100.000đ.':'Mẫu: LUMI10 · Thành viên · Đơn từ 100.000đ'}</p>`}</div><div class="cart-bottom"><div class="totals-line"><span>Tiền vé</span><strong>${D.money(t.tickets)}</strong></div><div class="totals-line"><span>Đồ ăn & thức uống</span><strong>${D.money(t.food)}</strong></div><div class="totals-line discount"><span>Giảm giá</span><strong>−${D.money(t.discount)}</strong></div><div class="grand-total"><span>Tổng thanh toán</span><strong>${D.money(t.total)}</strong></div>${d.paymentOrder?link('Xem thanh toán '+ic('arrow'),'orders/'+d.paymentOrder,'primary full'):btn('Thanh toán '+ic('arrow'),'checkout','primary full',!has||S().shift.status!=='open'?'disabled':'')}<p class="cart-footnote">${S().shift.status!=='open'?'Nhận ca để ghi nhận giao dịch.':'Giá đã bao gồm thuế · Không tự điều chỉnh giá'}</p></div></aside>`;
}
function draftDetail(){const d=S().draft;return `<div class="review-lines">${d.seats.map(l=>`<div><span>Ghế <strong>${l.seat}</strong> · ${seatNames[l.seatType]} · ${D.audience[l.type]} <small>${l.people} người</small></span><strong>${D.money(l.price)}${unit(l)}</strong></div>`).join('')}${d.products.map(p=>`<div><span>${D.products.find(x=>x.id===p.id).name} × ${p.qty}<small>${p.option}</small></span><strong>${D.money(p.price*p.qty)}</strong></div>`).join('')}</div>`;}
function checkout(){
 const d=S().draft,t=D.draftTotals(),sh=D.show(d.showId);if(d.paymentOrder)return empty('Đơn đang chờ thanh toán','Xem kết quả trước khi tiếp tục.',link('Xem thanh toán','orders/'+d.paymentOrder,'primary'));if(!d.seats.length&&!d.products.length)return empty('Đơn hiện tại chưa có dịch vụ','Chọn vé hoặc sản phẩm trước khi thanh toán.',link('Bắt đầu bán hàng',D.can('sell')?'sell':'food','primary'));
 const review=`<div class="padded">${sh?`<div class="checkout-show"><img src="assets/img/${D.movie(sh.movieId).art}.svg" alt=""><div><h2>${D.movie(sh.movieId).title}</h2><p>${S().cinema.name} · ${D.room(sh.roomId).name}</p><strong>${D.stamp(sh.start,true)}</strong><p>${D.room(sh.roomId).type} · ${D.room(sh.roomId).format} · ${D.room(sh.roomId).lang}</p></div><div class="hold-pill">${ic('clock')}<span id="hold-countdown">${holdText()}</span></div></div>`:''}${draftDetail()}<div class="notice compact">${ic('user')} ${d.customer?esc(d.customer.name)+' · '+mask(d.customer.phone):'Khách vãng lai · Không yêu cầu thông tin cá nhân'}</div>${d.seats.some(l=>l.type!=='adult')?`<div class="notice warning">${ic('alert')} Kiểm tra giấy tờ cho loại vé ưu tiên trước khi thu tiền.</div>`:''}</div>`;
 const payment=`<div class="padded"><div class="payment-methods">${[['cash','cash','Tiền mặt'],['qr','scan','QR chuyển khoản'],['card','card','Thẻ ngân hàng']].map(([k,i,l])=>btn(ic(i)+l,'payment-method',view.paymentMethod===k?'selected':'',`data-method="${k}" aria-pressed="${view.paymentMethod===k}"`)).join('')}</div><form data-form="payment" id="payment-form">${view.paymentMethod==='cash'?`<label class="cash-label">Số tiền khách đưa <span>VNĐ</span><input id="cash-received" name="received" type="number" min="${t.total}" step="1" inputmode="numeric" value="${esc(view.received)}" placeholder="Nhập số tiền thực nhận" required></label><div class="cash-presets">${[Math.ceil(t.total/50000)*50000,Math.ceil(t.total/100000)*100000,500000].filter((n,i,a)=>n>=t.total&&a.indexOf(n)===i).map(n=>btn(D.money(n),'cash-preset','secondary small',`data-value="${n}"`)).join('')}${btn('Đúng số tiền','cash-preset','secondary small',`data-value="${t.total}"`)}</div><div class="change-display"><span>Tiền trả lại khách</span><strong id="change-amount">${view.received&&Number(view.received)>=t.total?D.money(Number(view.received)-t.total):'—'}</strong></div><p id="cash-error" class="field-hint">Nhận và kiểm đếm đủ tiền trước khi xác nhận.</p>`:`<div class="notice">${ic('info')}<div><strong>Chờ kết quả từ ${view.paymentMethod==='qr'?'ngân hàng':'thiết bị POS'}</strong><p>Thao tác tiếp theo tạo yêu cầu minh họa. Mở màn hình không tự xác nhận đã thu tiền.</p></div></div>`}</form></div>`;
 return title('HOÀN TẤT ĐƠN HÀNG','Kiểm tra & thanh toán','Chỉ xuất vé sau khi giao dịch được xác nhận thành công.',link(ic('back')+' Quay lại đơn',sh?'sell?step=seats':'food'))+`<div class="checkout-layout"><div>${panel('1. Kiểm tra thông tin đơn',review)}${panel('2. Chọn phương thức thanh toán',payment)}<div class="subtle-note">${ic('lock')} Không nhập thông tin thẻ hoặc dữ liệu thanh toán thật.</div></div><aside class="panel checkout-summary"><span class="eyebrow">TÓM TẮT THANH TOÁN</span><h2>${d.seats.length?'Vé & dịch vụ':'Đơn đồ ăn'}</h2><div class="totals-line"><span>Tiền vé</span><strong>${D.money(t.tickets)}</strong></div><div class="totals-line"><span>Sản phẩm</span><strong>${D.money(t.food)}</strong></div><div class="totals-line discount"><span>Ưu đãi ${d.promo}</span><strong>−${D.money(t.discount)}</strong></div><div class="grand-total"><span>Tổng cần thu</span><strong>${D.money(t.total)}</strong></div><button type="submit" form="payment-form" class="btn primary full" ${S().shift.status==='open'?'':'disabled'}>${view.paymentMethod==='cash'?'Đã nhận đủ tiền · Hoàn tất':'Tạo yêu cầu thanh toán'} ${ic('arrow')}</button><p class="micro">${view.paymentMethod==='cash'?'Xác nhận sẽ ghi nhận giao dịch tiền mặt.':'Mô phỏng phản hồi ở bước tiếp theo.'}</p></aside></div>`;
}
function transactionsTable(trans){return `<div class="table-scroll"><table><thead><tr><th>Giao dịch / Đơn</th><th>Thời gian</th><th>Phương thức</th><th>Số tiền</th><th>Trạng thái</th></tr></thead><tbody>${trans.map(t=>`<tr><td><a class="table-link" href="#/transactions/${t.id}">${t.id}</a><small>${t.orderId}</small></td><td>${D.stamp(t.at)}</td><td>${methodName[t.method]}</td><td class="amount">${D.money(t.amount)}</td><td>${badge(paymentName[t.status],tone(t.status))}</td></tr>`).join('')||'<tr><td class="table-empty" colspan="5">Chưa có giao dịch.</td></tr>'}</tbody></table></div>`;}
function ordersPage(){
 const q=view.orderQuery.toLowerCase().trim();const list=S().orders.filter(o=>o.cinemaId===S().cinema.id&&(!q||o.id.toLowerCase().includes(q)||o.contact.includes(q)||S().tickets.some(t=>t.orderId===o.id&&t.id.toLowerCase().includes(q))||S().transactions.some(t=>t.orderId===o.id&&t.id.toLowerCase().includes(q)))&&(view.orderStatus==='all'||o.payment===view.orderStatus)&&(view.orderMethod==='all'||o.method===view.orderMethod)&&(view.orderTime==='all'||dateShort(o.created)===dateShort(D.now()))).sort((a,b)=>b.created-a.created);
 return title('ĐƠN HÀNG & THANH TOÁN','Tra cứu đơn hàng','Tìm đơn online và tại quầy trong phạm vi Lumi Nguyễn Trãi.',badge('Chỉ rạp được phân công'))+`<div class="notice warning compact">${ic('alert')} Giao dịch chưa rõ kết quả: tra cứu trước khi yêu cầu khách thanh toán lại.</div><section class="panel"><div class="order-filters"><label class="search-field">${ic('search')}<input id="order-search" data-filter="orderQuery" value="${esc(view.orderQuery)}" aria-label="Tìm đơn hàng" placeholder="Mã đơn, vé, giao dịch hoặc số điện thoại…"></label><label>Thời gian<select data-filter="orderTime"><option value="today" ${view.orderTime==='today'?'selected':''}>Hôm nay</option><option value="all" ${view.orderTime==='all'?'selected':''}>Tất cả ngày mẫu</option></select></label><label>Thanh toán<select data-filter="orderStatus"><option value="all">Tất cả trạng thái</option>${['paid','pending','unknown','failed','expired','cancelled'].map(k=>`<option value="${k}" ${view.orderStatus===k?'selected':''}>${paymentName[k]}</option>`).join('')}</select></label><label>Phương thức<select data-filter="orderMethod"><option value="all">Tất cả phương thức</option>${Object.entries(methodName).map(([k,l])=>`<option value="${k}" ${view.orderMethod===k?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="panel-head"><h2>${list.length} đơn hàng</h2><span class="micro">Thông tin liên hệ được che một phần</span></div><div class="table-scroll"><table><thead><tr><th>Mã đơn / Nguồn</th><th>Khách hàng</th><th>Vé / Sản phẩm</th><th>Tổng tiền</th><th>Đơn hàng</th><th>Thanh toán</th><th></th></tr></thead><tbody>${list.map(o=>`<tr><td><a class="table-link" href="#/orders/${o.id}">${o.id}</a><small>${o.source==='online'?'Mua online':'Tại quầy'} · ${D.stamp(o.created)}</small></td><td>${esc(o.customer)}<small>${mask(o.contact)}</small></td><td>${o.seatLines.length} vé · ${o.products.reduce((n,p)=>n+p.qty,0)} sản phẩm</td><td class="amount">${D.money(o.total)}</td><td>${badge(o.status==='confirmed'?'Đã xác nhận':o.status==='cancelled'?'Đã hủy':'Chờ xử lý',o.status==='confirmed'?'success':tone(o.status))}</td><td>${badge(paymentName[o.payment],tone(o.payment))}</td><td><a class="icon-btn" href="#/orders/${o.id}" aria-label="Mở đơn ${o.id}">${ic('chevron')}</a></td></tr>`).join('')||'<tr><td colspan="7" class="table-empty">Không có đơn phù hợp. Thử mã hoặc bộ lọc khác.</td></tr>'}</tbody></table></div></section>`;
}
function orderTickets(o){return o.seatLines.length?`<div class="padded">${o.seatLines.map(l=>{const sh=D.show(l.showId),r=D.room(sh.roomId),t=S().tickets.find(t=>t.orderId===o.id&&t.seat===l.seat);return `<div class="order-ticket"><span class="seat-chip large">${l.seat}</span><div><h3>${D.movie(sh.movieId).title}</h3><span>${r.name} · ${r.format} · ${r.type} · ${D.stamp(sh.start,true)}</span><small>${D.audience[l.type]} · ${l.people} người · ${D.money(l.price)}${unit(l)}</small><small>${t?t.id:'Vé chưa được phát hành'}</small></div>${t?badge(t.status==='used'?'Đã sử dụng':t.status==='cancelled'?'Đã hủy':'Chưa sử dụng',t.status==='valid'?'success':'neutral'):badge('Chờ thanh toán','warning')}</div>`;}).join('')}</div>`:'<div class="padded muted">Đơn chỉ có đồ ăn, không có vé xem phim.</div>';}
function orderDetail(id){
 const o=D.order(id);if(!o)return empty('Không tìm thấy đơn trong rạp','Kiểm tra mã hoặc phạm vi cụm rạp.',link('Tra cứu lại','orders','primary'));const trans=S().transactions.filter(t=>t.orderId===id),last=trans.at(-1);
 const goods=o.products.length?panel('Sản phẩm & giao nhận',`<div class="padded">${o.products.map(p=>`<div class="order-item"><img src="assets/img/${D.products.find(x=>x.id===p.id).image}.svg" alt=""><div><strong>${D.products.find(x=>x.id===p.id).name} × ${p.qty}</strong><span>${p.option}</span><small>Đã giao ${p.delivered}/${p.qty} · Còn ${p.qty-p.delivered}</small></div><strong>${D.money(p.price*p.qty)}</strong></div>`).join('')}${D.can('fulfillment')?link('Đến giao sản phẩm '+ic('arrow'),'fulfillment/'+id,'secondary full'):''}</div>`):'';
 const pay=`<div class="padded"><div class="totals-line"><span>Tiền vé</span><strong>${D.money(o.seatLines.reduce((n,l)=>n+l.price,0))}</strong></div><div class="totals-line"><span>Sản phẩm</span><strong>${D.money(o.products.reduce((n,p)=>n+p.price*p.qty,0))}</strong></div><div class="totals-line discount"><span>Giảm giá</span><strong>−${D.money(o.discount)}</strong></div><div class="grand-total"><span>Tổng tiền</span><strong>${D.money(o.total)}</strong></div>${trans.map(t=>`<a class="transaction-card" href="#/transactions/${t.id}"><div><strong>${t.id}</strong><span>${methodName[t.method]} · Lần ${t.attempt}</span></div>${badge(paymentName[t.status],tone(t.status))}</a>`).join('')}${o.payment==='paid'?link(ic('print')+' Vé & chứng từ','receipt/'+id,'primary full'):o.payment==='pending'?btn('Xem yêu cầu thanh toán','payment-status','primary full',`data-id="${id}"`):o.payment==='failed'?btn('Thử lại thanh toán','retry-payment','primary full',`data-id="${id}"`):''}</div>`;
 return title('CHI TIẾT ĐƠN HÀNG',id,`${o.source==='online'?'Mua online':'Mua tại quầy'} · ${D.stamp(o.created,true)} · ${esc(o.customer)} · ${mask(o.contact)}`,link(ic('back')+' Danh sách đơn','orders'))+`<div class="order-status-strip">${badge(o.status==='confirmed'?'Đơn đã xác nhận':o.status==='cancelled'?'Đơn đã hủy':'Đơn chờ xử lý',o.status==='confirmed'?'success':tone(o.status))}${badge(paymentName[o.payment],tone(o.payment))}${o.products.length?badge({waiting:'Đồ ăn chờ chuẩn bị',ready:'Đồ ăn sẵn sàng',delivered:'Đã giao đủ sản phẩm'}[o.foodStatus],tone(o.foodStatus)):''}</div>${o.payment==='unknown'?`<div class="notice warning">${ic('alert')}<div><strong>Chưa xác định kết quả thanh toán</strong><p>Không thu lại hoặc xuất vé. Tra cứu ${last.id} và chờ phản hồi xác thực.</p></div>${btn('Tra cứu kết quả','query-payment','primary small',`data-id="${id}"`)}</div>`:''}<div class="detail-grid"><div>${panel('Vé xem phim',orderTickets(o))}${goods}${panel('Lịch sử thao tác',`<ol class="timeline">${o.logs.slice().reverse().map(l=>`<li><span class="timeline-dot"></span><div><strong>${esc(l.text)}</strong><span>${D.stamp(l.at,true)} · ${esc(l.actor)}</span></div></li>`).join('')}</ol>`)}</div><div>${panel('Thanh toán',pay)}${['pending','failed'].includes(o.payment)&&o.status!=='cancelled'?`<div class="danger-zone"><p>Chỉ hủy đơn chưa thanh toán. Đơn chưa rõ kết quả cần tra cứu trước.</p>${btn('Hủy đơn chưa thanh toán','cancel-order','danger-outline',`data-id="${id}"`)}</div>`:''}</div></div>`;
}
function transactionPage(id){const t=D.tx(id),o=t&&D.order(t.orderId);if(!t||!o)return empty('Không tìm thấy giao dịch','Chỉ xem giao dịch của cụm rạp được phân công.',link('Tra cứu đơn','orders','primary'));return title('CHI TIẾT GIAO DỊCH',t.id,'Mã tham chiếu liên kết với đơn hàng.',link(ic('back')+' Đơn '+o.id,'orders/'+o.id))+`<div class="detail-grid">${panel('Thông tin giao dịch',`<dl class="info-grid padded"><dt>Mã tham chiếu</dt><dd>${t.id}</dd><dt>Đơn hàng</dt><dd><a href="#/orders/${o.id}">${o.id}</a></dd><dt>Phương thức</dt><dd>${methodName[t.method]}</dd><dt>Số tiền</dt><dd>${D.money(t.amount)}</dd><dt>Trạng thái</dt><dd>${badge(paymentName[t.status],tone(t.status))}</dd><dt>Lần thanh toán</dt><dd>${t.attempt}</dd><dt>Tạo lúc</dt><dd>${D.stamp(t.at,true)}</dd>${t.method==='cash'?`<dt>Khách đưa</dt><dd>${D.money(t.received)}</dd><dt>Tiền thừa</dt><dd>${D.money(t.received-t.amount)}</dd>`:''}</dl>`)}<section class="panel padded"><h2>Hướng xử lý</h2><p>${t.status==='unknown'?'Chưa rõ kết quả. Cần tra cứu giao dịch trước khi thu lại.':t.status==='success'?'Thanh toán thành công. Có thể xuất vé và chứng từ.':'Kiểm tra trạng thái mới nhất trước khi phục vụ khách.'}</p>${['pending','unknown'].includes(t.status)?btn('Tra cứu kết quả minh họa','query-payment','primary',`data-id="${o.id}"`):link('Mở đơn hàng '+ic('arrow'),'orders/'+o.id,'primary')}</section></div>`;}
function qr(code){let cells='';const h=[...code].reduce((n,c)=>n*31+c.charCodeAt(0),7)>>>0;for(let y=0;y<25;y++)for(let x=0;x<25;x++){if((x<8&&y<8)||(x>16&&y<8)||(x<8&&y>16))continue;if((x*17+y*13+h+x*y*7)%19<9)cells+=`<rect x="${x}" y="${y}" width="1" height="1"/>`;}const f=(x,y)=>`<rect x="${x}" y="${y}" width="7" height="7"/><rect x="${x+1}" y="${y+1}" width="5" height="5" fill="white"/><rect x="${x+2}" y="${y+2}" width="3" height="3"/>`;return `<svg viewBox="-2 -2 29 29" class="qr-demo" role="img" aria-label="QR minh họa cho ${esc(code)}; dùng mã chữ để tra cứu"><rect x="-2" y="-2" width="29" height="29" fill="white"/><g fill="#173e35">${cells}${f(0,0)}${f(18,0)}${f(0,18)}</g></svg>`;}
function ticketCard(t,o){const sh=D.show(t.showId),m=D.movie(sh.movieId),r=D.room(sh.roomId);return `<article class="ticket-card"><div class="ticket-brand"><strong>lumi<span> CINEMA</span></strong>${badge(t.status==='used'?'Đã sử dụng':t.status==='cancelled'?'Đã hủy':'Chưa sử dụng',t.status==='valid'?'success':'neutral')}</div><div class="ticket-body"><div><span class="eyebrow">VÉ XEM PHIM · ${t.people} NGƯỜI</span><h2>${m.title}</h2><p>${S().cinema.name} · ${r.name}</p><strong>${D.stamp(sh.start,true)}</strong><p>${r.type} · ${r.format} · ${r.lang}</p><div class="ticket-seat">GHẾ <strong>${t.seat}</strong><span>${D.audience[t.type]}<br>${D.money(t.price)}${unit(t)}</span></div></div><div class="ticket-code">${qr(t.id)}<strong>${t.id}</strong><small>QR MINH HỌA</small></div></div><div class="ticket-bottom"><span>${o.id}</span><span>Vui lòng đến trước giờ chiếu 15 phút.</span></div></article>`;}
function receiptPage(id){const o=D.order(id);if(!o||o.payment!=='paid')return empty('Chưa thể xuất chứng từ','Đơn cần được xác nhận thanh toán thành công.',link('Tra cứu đơn','orders','primary'));return title('THANH TOÁN THÀNH CÔNG','Vé & chứng từ bán hàng',`${id} · ${D.money(o.total)} · ${methodName[o.method]}`,btn(ic('plus')+' Đơn mới','new-sale','primary'))+`<div class="notice success">${ic('check')}<div><strong>Đã xác nhận thanh toán</strong><span>Kiểm tra vé, ghế và sản phẩm trước khi giao khách.</span></div></div><div class="receipt-layout"><div>${S().tickets.filter(t=>t.orderId===id&&t.cinemaId===S().cinema.id).map(t=>ticketCard(t,o)).join('')||panel('Đơn đồ ăn độc lập','<div class="padded">Đơn không có vé. In phiếu nhận đồ ăn để giao khách.</div>')}${o.products.length?panel('Phiếu nhận đồ ăn',`<div class="padded food-slip"><div>${qr('SP-'+id.slice(3))}<strong>SP-${id.slice(3)}</strong><small>QR minh họa · Dùng mã chữ</small></div><div><h3>Nhận tại quầy đồ ăn</h3>${o.products.map(p=>`<p><strong>${p.qty} × ${D.products.find(x=>x.id===p.id).name}</strong><br><small>${p.option}</small></p>`).join('')}<p class="micro">Tra cứu số lượng còn lại bằng mã đơn ${id}.</p></div></div>`):''}</div><aside class="panel padded print-actions"><span class="eyebrow">GIAO CHO KHÁCH</span><h2>In & bàn giao</h2><p>In lại ghi nhận người và thời gian, không thay đổi trạng thái sử dụng vé.</p>${o.seatLines.length?btn(ic('print')+' In vé xem phim','print-order','primary full',`data-id="${id}" data-kind="tickets"`):''}${o.products.length?btn(ic('print')+' In phiếu đồ ăn','print-order','secondary full',`data-id="${id}" data-kind="food"`):''}${btn(ic('print')+' In biên nhận','print-order','secondary full',`data-id="${id}" data-kind="receipt"`)}${link('Xem chi tiết đơn '+ic('arrow'),'orders/'+id,'text-btn full')}<div class="notice compact">${ic('info')} QR chỉ là hình minh họa. Nhập mã vé ở Soát vé để kiểm tra.</div></aside></div>`;}
function scanPage(){return title('KIỂM SOÁT LỐI VÀO','Soát vé','Kiểm tra từng vé, đúng số người và phòng chiếu.',badge('Thiết bị quét / Bàn phím'))+`<div class="scan-layout"><section class="panel scan-console"><div class="scanner-visual">${ic('scan')}<span>SẴN SÀNG NHẬN MÃ</span></div><form data-form="scan" class="scan-form"><label for="scan-code">Mã vé xem phim</label><div class="input-action"><input id="scan-code" name="code" placeholder="VD: VE-1001-1" autocomplete="off" spellcheck="false" required><button type="submit" class="btn primary">Kiểm tra ${ic('arrow')}</button></div></form><div class="scanner-actions">${btn(ic('scan')+' Mô phỏng quét QR','demo-scan','secondary')}<span>Thiết bị quét có thể nhập mã rồi nhấn Enter.</span></div>${view.scanResult?scanResult(view.scanResult):`<div class="scan-idle">${ic('ticket')}<h2>Mỗi vé, một lần xác nhận.</h2><p>Kết quả kiểm tra sẽ xuất hiện tại đây.<br>Quét mã chưa tự xác nhận khách đã vào rạp.</p></div>`}</section><aside>${panel('Mã vé để thử',`<div class="sample-codes">${[['VE-1001-1','Hợp lệ · Ghế D5'],['VE-1001-2','Vé thứ hai cùng đơn'],['VE-1006-1','Đã sử dụng'],['VE-1007-1','Sai cụm rạp'],['VE-1008-1','Không đúng thời điểm'],['VE-1009-1','Đã hủy'],['VE-9999-1','Không tìm thấy']].map(([c,l])=>btn(`<strong>${c}</strong><span>${l}</span>`,'scan-sample','',`data-code="${c}"`)).join('')}</div>`)}<div class="notice">${ic('info')}<p>Chỉ xác nhận vé hợp lệ. Đơn nhiều vé phải được kiểm tra riêng từng mã, không đánh dấu cả đơn đã đến.</p></div></aside></div>`;}
function scanResult(res){const t=res.ticket,sh=res.show,valid=res.status==='valid',done=res.status==='checked';return `<div class="scan-result ${valid||done?'valid':'invalid'}"><div class="scan-result-title">${ic(valid||done?'check':'alert')}<div><span>KẾT QUẢ KIỂM TRA</span><h2>${res.label}</h2></div></div><p>${esc(res.message)}</p>${t&&sh?`<div class="scan-ticket-info"><h3>${D.movie(sh.movieId).title}</h3><div><span>Phòng chiếu<strong>${D.room(sh.roomId).name}</strong></span><span>Giờ chiếu<strong>${D.stamp(sh.start)}</strong></span><span>Ghế<strong>${t.seat}</strong></span><span>Số người<strong>${t.people} người</strong></span></div><small>${t.id} · ${dateShort(sh.start)} · ${D.room(sh.roomId).format}</small></div>`:''}${valid?btn(ic('check')+` Xác nhận ${t.people} người vào phòng`,'checkin','primary full',`data-code="${t.id}"`):done?btn('Kiểm tra vé tiếp theo','next-scan','secondary full'):''}</div>`;}
function fulfillmentPage(id){const all=S().orders.filter(o=>o.cinemaId===S().cinema.id&&o.products.length),q=view.fulfillQuery.trim().toUpperCase(),list=all.filter(o=>(view.foodStatus==='all'||o.foodStatus===view.foodStatus)&&(!q||o.id.includes(q)||('SP-'+o.id.slice(3)).includes(q))).sort((a,b)=>a.created-b.created),selected=id&&D.order(id);return title('QUẦY ĐỒ ĂN / GIAO NHẬN','Tiếp nhận & giao sản phẩm','Kiểm tra thanh toán và số lượng còn lại trước khi giao.',badge('Hỗ trợ giao từng phần','success'))+`<div class="fulfillment-layout"><section class="panel"><div class="padded"><label class="search-field">${ic('search')}<input id="fulfill-search" data-filter="fulfillQuery" value="${esc(view.fulfillQuery)}" placeholder="Mã đơn hoặc mã nhận sản phẩm…" aria-label="Tìm đơn giao sản phẩm"></label></div><div class="category-tabs fulfillment-tabs">${[['ready','Sẵn sàng'],['waiting','Chờ chuẩn bị'],['delivered','Đã giao'],['all','Tất cả']].map(([k,l])=>btn(`${l} <span>${all.filter(o=>k==='all'||o.foodStatus===k).length}</span>`,'fulfill-status',view.foodStatus===k?'active':'',`data-status="${k}"`)).join('')}</div><div class="fulfillment-list">${list.map(o=>`<a href="#/fulfillment/${o.id}" class="fulfillment-order ${id===o.id?'selected':''}"><div><strong>${o.id}</strong><span>SP-${o.id.slice(3)} · ${D.stamp(o.created)}</span></div>${badge(paymentName[o.payment],tone(o.payment))}<p>${o.products.map(p=>`${p.qty} × ${D.products.find(x=>x.id===p.id).name}`).join(' · ')}</p><div class="fulfillment-progress"><span>Đã giao ${o.products.reduce((n,p)=>n+p.delivered,0)}/${o.products.reduce((n,p)=>n+p.qty,0)} sản phẩm</span>${ic('chevron')}</div></a>`).join('')||empty('Không có đơn phù hợp','Đổi trạng thái hoặc thử mã khác.')}</div></section><section class="panel fulfillment-detail">${selected&&selected.products.length?fulfillmentDetail(selected):empty('Chọn một đơn để xử lý','Xem món, tùy chọn và số lượng cần giao tại đây.')}</section></div>`;}
function fulfillmentDetail(o){return `<div class="panel-head"><div><span class="eyebrow">MÃ NHẬN SP-${o.id.slice(3)}</span><h2>${o.id}</h2></div>${badge({waiting:'Chờ chuẩn bị',ready:'Sẵn sàng',delivered:'Đã giao đủ'}[o.foodStatus],tone(o.foodStatus))}</div><div class="padded">${o.payment==='paid'?`<div class="notice success compact">${ic('check')} Đã thanh toán · ${methodName[o.method]}</div>`:`<div class="notice danger">${ic('alert')} Chưa xác nhận thanh toán. Không giao sản phẩm; chuyển về quầy tra cứu.</div>`}<form data-form="deliver" data-id="${o.id}"><input type="hidden" name="deliveryVersion" value="${o.deliveryVersion||0}">${o.products.map(p=>`<div class="delivery-item"><img src="assets/img/${D.products.find(x=>x.id===p.id).image}.svg" alt=""><div><h3>${D.products.find(x=>x.id===p.id).name}</h3><p>${p.option}</p><span>Đặt ${p.qty} · Đã giao ${p.delivered} · <strong>Còn ${p.qty-p.delivered}</strong></span></div><label>Giao lần này<input type="number" name="${p.key}" min="0" max="${p.qty-p.delivered}" step="1" value="${p.qty-p.delivered}" inputmode="numeric" ${o.payment!=='paid'||o.foodStatus!=='ready'||p.delivered===p.qty?'disabled':''}></label></div>`).join('')}<label class="delivery-note">Ghi chú đơn<textarea rows="2" readonly>${esc(o.note||'Không có ghi chú.')}</textarea></label>${o.foodStatus==='ready'?`<button type="submit" class="btn primary full" ${o.payment!=='paid'||S().shift.status!=='open'?'disabled':''}>${ic('check')} Xác nhận giao số lượng đã chọn</button>`:o.foodStatus==='waiting'?btn('Đánh dấu đã chuẩn bị xong','food-ready','primary full',`data-id="${o.id}" ${o.payment!=='paid'||S().shift.status!=='open'?'disabled':''}`):'<div class="notice success">Đơn đã giao đủ, không thể xác nhận giao thêm.</div>'}</form>${D.can('orders')?link('Xem đơn & lịch sử '+ic('arrow'),'orders/'+o.id,'text-btn full'):''}</div>`;}
function roomsPage(){const shows=S().shows.filter(s=>dateShort(s.start)===dateShort(D.now()));return title('THEO DÕI VẬN HÀNH','Phòng & suất chiếu','Theo dõi trong ngày. Nhân viên không tự đổi phòng hoặc sửa lịch.',btn(ic('alert')+' Báo sự cố','incident','secondary'))+`<div class="room-grid">${D.roomDefs.map(r=>panel(`${r.name} <span class="room-type">${r.type}</span>`,`<div class="padded">${S().roomWarnings[r.id]?`<div class="notice warning compact">${ic('alert')} ${S().roomWarnings[r.id]}</div>`:''}${shows.filter(s=>s.roomId===r.id).sort((a,b)=>a.start-b.start).map(sh=>{const tickets=S().tickets.filter(t=>t.showId===sh.id&&t.cinemaId===S().cinema.id&&t.status!=='cancelled');return `<div class="room-show"><div class="room-show-top"><strong>${D.stamp(sh.start)} <span>– ${D.stamp(sh.start+D.movie(sh.movieId).duration*60000)}</span></strong>${badge(D.showStatus(sh),tone(D.showStatus(sh)))}</div><h3>${D.movie(sh.movieId).title}</h3><p>${r.format} · ${r.lang}</p><div class="room-show-count"><span>${ic('ticket')} Đã bán <strong>${tickets.reduce((n,t)=>n+t.people,0)} người</strong></span><span>${ic('scan')} Đã vào <strong>${tickets.filter(t=>t.status==='used').reduce((n,t)=>n+t.people,0)} người</strong></span></div>${btn('Báo sự cố','incident','text-btn',`data-id="${sh.id}"`)}</div>`;}).join('')||'<p>Chưa có suất hôm nay.</p>'}</div>`,badge('Đang hoạt động','success'))).join('')}</div>${panel('Sự cố đã ghi nhận',S().incidents.length?`<div class="table-scroll"><table><thead><tr><th>Thời gian</th><th>Phòng / Suất</th><th>Mức độ</th><th>Nội dung</th><th>Người báo</th></tr></thead><tbody>${S().incidents.slice().reverse().map(i=>`<tr><td>${D.stamp(i.at)}</td><td>${D.room(i.roomId).name}${i.showId?'<small>'+D.stamp(D.show(i.showId).start)+'</small>':''}</td><td>${badge(i.level,i.level==='Khẩn cấp'?'danger':'warning')}</td><td>${esc(i.content)}</td><td>${esc(i.actor)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="padded muted">Chưa có báo cáo sự cố mới trong bản mô phỏng.</div>')}`;}
function shiftPage(){
 const s=S(),st=s.shift.report||D.stats(),cashier=D.hasCashier()&&s.shift.cashier;
 if(!D.hasCashier()&&s.shift.cashier)return title('CA LÀM VIỆC','Thông tin ca hiện tại','Ca hiện tại có nghiệp vụ thu ngân.')+panel('Thông tin được phân công',`<div class="padded"><p>${s.staff.name} · ${s.shift.id}</p><p>${s.cinema.name} · ${s.counter}</p>${badge(s.shift.status==='closed'?'Ca đã kết thúc':'Ca đang mở',s.shift.status==='open'?'success':'neutral')}<div class="notice">Vai trò soát vé không xem số liệu thu ngân. Chọn vai trò thu ngân hoặc trưởng ca để đối soát và kết ca có tiền mặt.</div></div>`);
 if(s.shift.status==='pending')return title('NHẬN CA & BÀN GIAO','Nhận ca làm việc','Xác nhận quầy và tiền mặt trước khi bắt đầu giao dịch.')+`<div class="receive-grid"><section class="panel padded"><span class="eyebrow">SẴN SÀNG BẮT ĐẦU</span><h2>${s.shift.id}</h2><dl class="info-grid"><dt>Cụm rạp</dt><dd>${s.cinema.name}</dd><dt>Quầy làm việc</dt><dd>${s.counter}</dd><dt>Nhân viên</dt><dd>${s.staff.name} · ${s.staff.id}</dd><dt>Vai trò</dt><dd>${D.roles[s.role].name}</dd><dt>Thời gian nhận</dt><dd>${D.stamp(D.now(),true)}</dd></dl><form data-form="open-shift">${D.hasCashier()?'<label>Tiền mặt đầu ca (VNĐ)<input type="number" name="opening" min="0" step="1" value="1000000" inputmode="numeric" required></label>':'<div class="notice">Ca soát vé không phụ trách thu ngân, không yêu cầu tiền mặt đầu ca.</div>'}<label class="checkbox-line"><input type="checkbox" required> Tôi đã kiểm tra quầy và tiếp nhận bàn giao.</label><button class="btn primary full" type="submit">${ic('check')} Nhận ca & bắt đầu làm việc</button></form></section><aside class="welcome-shift"><span class="eyebrow">BẮT ĐẦU TỪ NHỮNG ĐIỀU NHỎ</span><h2>Một quầy sẵn sàng.<br>Một ca suôn sẻ.</h2><p>Kiểm tra máy in, thiết bị thanh toán và máy quét trước khi đón vị khách đầu tiên.</p><ul><li>Đúng cụm rạp được phân công</li><li>Tiền mặt đầu ca đã kiểm đếm</li><li>Lưu ý vận hành đã tiếp nhận</li></ul></aside></div>`;
 const moneyCards=cashier?statCard('Giao dịch thành công',st.count,'Tại quầy · Trong ca','orders')+statCard('Tổng thu trong ca',D.money(st.revenue),'Sau giảm giá','wallet')+statCard('Tiền mặt đã thu',D.money(st.cash),'Không gồm đầu ca','cash')+statCard('Không tiền mặt',D.money(st.card+st.qr),'Thẻ + QR thành công','card'):statCard('Vé đã soát',s.tickets.filter(t=>t.checkedBy===s.staff.name&&t.checkedAt>=s.shift.start).length,'Từng vé đã xác nhận trong ca','scan');
 const methodPanel=cashier?panel('Đối soát theo phương thức',`<div class="table-scroll"><table><thead><tr><th>Phương thức</th><th>Thành công</th><th>Số tiền</th></tr></thead><tbody>${['cash','qr','card'].map(m=>`<tr><td>${methodName[m]}</td><td>${s.transactions.filter(t=>t.shiftId===s.shift.id&&t.status==='success'&&t.method===m&&D.order(t.orderId)?.source==='counter').length}</td><td class="amount">${D.money(st[m])}</td></tr>`).join('')}</tbody></table></div>`)+panel('Giao dịch cần bàn giao',st.unknown.length?transactionsTable(st.unknown):'<div class="padded muted">Không còn giao dịch chờ hoặc chưa rõ kết quả.</div>'):'';
 const counted=cashier?`<div class="totals-line"><span>Tiền mặt đầu ca</span><strong>${D.money(s.shift.opening)}</strong></div><div class="totals-line"><span>Thu tiền mặt trong ca</span><strong>${D.money(st.cash)}</strong></div><div class="grand-total"><span>Tiền mặt dự kiến</span><strong>${D.money(st.expected)}</strong></div>`:'';
 const closed=s.shift.status==='closed';
 const form=closed?`${cashier?`<div class="totals-line"><span>Thực tế kiểm đếm</span><strong>${D.money(s.shift.counted)}</strong></div><div class="notice ${s.shift.counted===st.expected?'success':'warning'}">Chênh lệch: ${D.money(s.shift.counted-st.expected)}</div><p>${esc(s.shift.note||'Đối soát khớp tiền mặt.')}</p>`:''}<div class="notice success">${ic('lock')} Ca đã kết thúc, không tiếp nhận giao dịch mới.</div>${btn('Chuẩn bị ca tiếp theo','next-shift','secondary full')}`:`<form data-form="close-shift">${cashier?'<label>Tiền kiểm đếm thực tế (VNĐ)<input name="counted" id="counted-cash" type="number" min="0" step="1" inputmode="numeric" required placeholder="Nhập số tiền đã đếm"></label><div class="change-display"><span>Chênh lệch</span><strong id="cash-difference">—</strong></div><label>Giải thích chênh lệch<textarea name="note" rows="2" placeholder="Bắt buộc khi có sai lệch"></textarea></label>':''}<label>Nội dung bàn giao ${st.unknown.length?'<span class="required">*</span>':''}<textarea name="handover" rows="3" ${st.unknown.length?'required':''} placeholder="Mã giao dịch cần tra cứu, việc còn lại…"></textarea></label><label class="checkbox-line"><input type="checkbox" required> Tôi xác nhận số liệu và đã chuẩn bị bàn giao.</label><button class="btn primary full" type="submit">${ic('lock')} Xác nhận kết ca</button></form>`;
 return title('NHẬN CA & BÀN GIAO',closed?'Biên bản kết ca':'Đối soát & kết ca',`${s.shift.id} · ${s.staff.name} · Bắt đầu ${D.stamp(s.shift.start,true)}`,closed?btn(ic('print')+' In biên bản','print-shift','primary'):badge('Đang làm việc','success'))+`<div class="stats-grid">${moneyCards}</div><div class="detail-grid"><div>${methodPanel}${closed?panel('Nội dung bàn giao',`<div class="padded"><p>${esc(s.shift.handover||'Không có việc cần bàn giao.')}</p><p class="micro">Kết thúc: ${D.stamp(s.shift.end,true)}</p></div>`):`<div class="notice warning">${ic('info')} Ghi các giao dịch chưa rõ kết quả vào bàn giao. Kết ca không làm giao dịch thành công.</div>`}</div><section class="panel padded"><h2>${cashier?'Kiểm đếm tiền mặt':'Xác nhận bàn giao'}</h2>${counted}${form}</section></div>`;
}
function accountPage(){return title('THÔNG TIN & TRỢ GIÚP','Tài khoản & hướng dẫn','Thông tin được phân công và hướng dẫn thao tác nhanh tại rạp.')+`<div class="detail-grid"><div>${panel('Thông tin nhân viên',`<div class="padded"><div class="account-profile"><span class="avatar large">MA</span><div><h2>${S().staff.name}</h2><p>${S().staff.id} · Nhân viên vận hành</p></div></div><dl class="info-grid"><dt>Rạp được phân công</dt><dd>${S().cinema.name}</dd><dt>Địa chỉ</dt><dd>${S().cinema.address}</dd><dt>Quầy hiện tại</dt><dd>${S().counter}</dd><dt>Vai trò đang thử</dt><dd>${D.roles[S().role].name}</dd><dt>Ca hiện tại</dt><dd>${S().shift.id} · ${{open:'Đang mở',closed:'Đã kết thúc',pending:'Chưa nhận'}[S().shift.status]}</dd></dl></div>`)}${panel('Hướng dẫn nghiệp vụ',`<div class="help-list">${[['Bán vé tại quầy','Nhận ca → chọn suất → chọn ghế → chọn đối tượng vé → đồ ăn → kiểm tra → thanh toán → in. Giá vé hiển thị theo lựa chọn; nhân viên không tự sửa giá.'],['Thanh toán chưa rõ kết quả','Tra cứu mã giao dịch tại Đơn & giao dịch. Chỉ thu lại khi đã có kết quả thất bại xác thực. Không coi ảnh chụp chuyển khoản là kết quả thành công.'],['Xuất lại vé','Mở đơn đã thanh toán → Vé & chứng từ → In vé. Thao tác ghi nhận thời gian và người in, không thay trạng thái đã sử dụng.'],['Soát vé','Quét hoặc nhập mã từng vé rồi Enter. Chỉ xác nhận khi kết quả hợp lệ, đúng rạp, đúng thời gian và đúng số người.'],['Giao sản phẩm từng phần','Chọn đơn đã thanh toán, đánh dấu sẵn sàng. Nhập số lượng giao lần này, hệ thống giữ lại số lượng còn thiếu.'],['Kết ca','Kiểm đếm tiền, giải thích chênh lệch, ghi giao dịch cần tra cứu vào bàn giao rồi xác nhận kết ca.']].map(([h,p])=>`<details><summary>${h}${ic('down')}</summary><p>${p}</p></details>`).join('')}</div>`)}</div><aside>${panel('Phím tắt',`<dl class="keyboard-list">${[['F2','Bán vé tại quầy'],['F3','Quầy đồ ăn'],['F4','Tra cứu đơn'],['F6','Soát vé'],['/','Tập trung ô tìm kiếm'],['Alt + L','Khóa màn hình'],['Esc','Đóng hộp thoại']].map(([k,v])=>`<div><dt><kbd>${k}</kbd></dt><dd>${v}</dd></div>`).join('')}</dl>`)}${panel('Thông báo vận hành','<div class="padded"><div class="notice warning compact">Phòng 04: kiểm tra điều hòa trước suất 15:15.</div><p>Quy trình mở cửa phòng: từ 60 phút trước giờ chiếu. Nhắc khách đến sớm 15 phút.</p><p>Ca có giao dịch chưa rõ kết quả cần ghi mã tham chiếu vào biên bản bàn giao.</p></div>')}<div class="demo-settings"><h3>Dữ liệu mô phỏng</h3><p>Khôi phục sẽ xóa các đơn và thao tác bạn đã thử trên trình duyệt này.</p>${S().shift.status==='open'?btn('Thử tình huống chưa nhận ca','demo-pending-shift','secondary full'):''}${btn(ic('refresh')+' Khôi phục dữ liệu mẫu','reset-demo','danger-outline')}</div></aside></div>`;}
function render(){route=currentRoute();if(!S().session||S().locked){$('#app').innerHTML=login(S().locked);return;}
let permission={checkout:D.can('sell')?'sell':'food',receipt:'orders',transactions:'orders'}[route.page]||route.page;
if(!D.can(permission)){ $('#app').innerHTML=shell(empty('Chức năng ngoài quyền hiện tại','Chọn chức năng được cấp quyền hoặc đổi vai trò mô phỏng.',link('Về tổng quan','dashboard','primary')));return; }
const pages={dashboard, sell:sale, food:foodPage, orders:()=>route.id?orderDetail(route.id):ordersPage(),checkout, receipt:()=>receiptPage(route.id), transactions:()=>transactionPage(route.id), scan:scanPage, fulfillment:()=>fulfillmentPage(route.id),rooms:roomsPage,shift:shiftPage,account:accountPage};
$('#app').innerHTML=shell(pages[route.page]?pages[route.page]():empty('Không tìm thấy màn hình','Kiểm tra đường dẫn hoặc trở về tổng quan.',link('Về tổng quan','dashboard','primary')));if(route.page==='scan')setTimeout(()=>$('#scan-code')?.focus(),0);
}
function paymentDialog(id,lookup=false){const o=D.order(id);if(!o)throw Error('Không tìm thấy đơn.');const t=S().transactions.filter(t=>t.orderId===id).at(-1);if(o.payment==='paid'){go('receipt/'+id);return;}dialog(lookup?'Tra cứu kết quả giao dịch':'Yêu cầu thanh toán minh họa',`<div class="payment-dialog"><div class="notice ${o.payment==='unknown'?'warning':''}">${ic('info')}<div><strong>Đây là phản hồi giả lập, không kết nối ngân hàng.</strong><p>Chọn tình huống để kiểm thử. Chưa có kết quả thành công thì không xuất vé.</p></div></div>${o.method==='qr'&&!lookup?`<div class="payment-qr">${qr(t.id)}<small>QR MINH HỌA · KHÔNG DÙNG CHUYỂN TIỀN</small></div>`:''}<dl class="info-grid"><dt>Đơn hàng</dt><dd>${id}</dd><dt>Mã tham chiếu</dt><dd>${t.id}</dd><dt>Số tiền</dt><dd><strong>${D.money(o.total)}</strong></dd><dt>Trạng thái</dt><dd>${badge(paymentName[o.payment],tone(o.payment))}</dd></dl><label for="payment-result">${lookup?'Phản hồi tra cứu giả lập':'Mô phỏng phản hồi từ cổng thanh toán'}</label><select id="payment-result"><option value="success">Đã nhận tiền — thành công</option><option value="failed">Không thu được tiền — thất bại</option>${o.payment!=='unknown'?'<option value="expired">Yêu cầu hết hạn</option>':''}<option value="unknown">Chưa xác định được kết quả</option></select><div class="modal-actions">${btn('Đóng, giữ nguyên trạng thái','close-modal')}${btn(lookup?'Nhận phản hồi tra cứu':'Nhận kết quả mô phỏng','settle-payment','primary',`data-id="${id}"`)}</div></div>`);}
function customerDialog(){dialog('Tìm thành viên',`<p>Tìm bằng mã hoặc số điện thoại. Thông tin mẫu: <strong>TV0088</strong> / <strong>0918765432</strong>.</p><form data-form="customer"><label>Mã thành viên hoặc số điện thoại<input name="query" placeholder="Nhập mã hoặc số điện thoại" required autocomplete="off"></label><button type="submit" class="btn primary full">${ic('search')} Tìm thành viên</button></form><div id="customer-results"></div><div class="modal-actions">${btn('Tiếp tục với khách vãng lai','guest','text-btn')}</div>`);}
function selectShow(id){D.requireOpen();if(!D.can('sell'))throw Error('Vai trò hiện tại không được bán vé.');const sh=D.show(id);if(!sh||D.showStatus(sh)!=='Đang bán')throw Error('Suất không còn bán vé. Chọn suất khác.');const d=S().draft;if(d.paymentOrder)throw Error('Đơn hiện tại đang thanh toán. Xử lý kết quả trước khi đổi suất.');const select=()=>{if(d.showId!==id){d.showId=id;d.seats=[];d.holdUntil=null;d.promo='';}D.save();go('sell?step=seats');};if(d.seats.length&&d.showId!==id)confirmAction('Đổi suất chiếu?','Các ghế đã chọn sẽ được bỏ. Sản phẩm đồ ăn vẫn giữ trong đơn.',select,'Đổi suất');else select();}
function printOrder(id,kind){const o=D.order(id);if(!o||o.payment!=='paid')throw Error('Chỉ in chứng từ của đơn đã thanh toán.');const previous=o.logs.some(l=>l.text.startsWith('In ')&&l.text.includes({tickets:'vé xem phim',food:'phiếu đồ ăn',receipt:'biên nhận'}[kind]));D.audit(`${previous?'In lại':'In lần đầu'} ${{tickets:'vé xem phim',food:'phiếu đồ ăn',receipt:'biên nhận'}[kind]} · ${id}`,o);D.save();const name={tickets:'VÉ XEM PHIM',food:'PHIẾU NHẬN ĐỒ ĂN',receipt:'BIÊN NHẬN BÁN HÀNG'}[kind];let content='';if(kind==='tickets')content=S().tickets.filter(t=>t.orderId===id&&t.cinemaId===S().cinema.id).map(t=>ticketCard(t,o)).join('');else if(kind==='food')content=`<h2>Mã nhận SP-${id.slice(3)}</h2>${qr('SP-'+id.slice(3))}<p>${o.products.map(p=>`${p.qty} × ${D.products.find(x=>x.id===p.id).name} · ${p.option}`).join('<br>')}</p>`;else content=`<p>${o.customer} · ${methodName[o.method]}</p><table><thead><tr><th>Dịch vụ</th><th>Thành tiền</th></tr></thead><tbody>${o.seatLines.map(l=>`<tr><td>Ghế ${l.seat} · ${D.audience[l.type]} · ${l.people} người</td><td>${D.money(l.price)}</td></tr>`).join('')}${o.products.map(p=>`<tr><td>${p.qty} × ${D.products.find(x=>x.id===p.id).name} (${p.option})</td><td>${D.money(p.qty*p.price)}</td></tr>`).join('')}</tbody></table><p>Giảm giá: −${D.money(o.discount)}</p><h2>Tổng thanh toán: ${D.money(o.total)}</h2><p>Giao dịch: ${S().transactions.filter(t=>t.orderId===id&&t.status==='success').map(t=>t.id).join(', ')}</p>`;
$('#print-root').innerHTML=`<div class="print-heading"><h1>LUMI CINEMA · ${name}</h1><p>${esc(S().cinema.name)} · ${id}</p></div>${content}<p class="print-foot">Chứng từ mô phỏng · ${previous?'Xuất lại':'Xuất lần đầu'} bởi ${S().staff.name}<br>${D.stamp(D.now(),true)} · Không phải hóa đơn tài chính.</p>`;window.print();render();toast('Đã mở hộp thoại in và ghi nhận lịch sử.');}
function printShift(){const s=S().shift,st=s.report;if(s.status!=='closed')throw Error('Kết ca trước khi in biên bản.');D.audit('In biên bản '+s.id);D.save();$('#print-root').innerHTML=`<h1>LUMI CINEMA · BIÊN BẢN KẾT CA</h1><p>${S().cinema.name} · ${S().counter}</p><p>${s.id} · ${S().staff.name}</p><p>Bắt đầu: ${D.stamp(s.start,true)}<br>Kết thúc: ${D.stamp(s.end,true)}</p>${s.cashier?`<table><tbody><tr><th>Đầu ca</th><td>${D.money(s.opening)}</td></tr><tr><th>Thu tiền mặt</th><td>${D.money(st.cash)}</td></tr><tr><th>Thu QR</th><td>${D.money(st.qr)}</td></tr><tr><th>Thu thẻ</th><td>${D.money(st.card)}</td></tr><tr><th>Tiền mặt dự kiến</th><td>${D.money(st.expected)}</td></tr><tr><th>Kiểm đếm thực tế</th><td>${D.money(s.counted)}</td></tr><tr><th>Chênh lệch</th><td>${D.money(s.counted-st.expected)}</td></tr></tbody></table><p>Giải thích: ${esc(s.note||'Không có chênh lệch')}</p>`:''}<h2>Công việc bàn giao</h2><p>${esc(s.handover||'Không có')}</p><p>Giao dịch chờ / chưa rõ: ${st.unknown.map(t=>`${t.id} (${D.money(t.amount)})`).join(', ')||'Không có'}</p><p>Người bàn giao: _____________________</p><p>Người nhận bàn giao: _____________________</p><small>Biên bản mô phỏng · ${D.stamp(D.now(),true)}</small>`;window.print();}
const actionPermissions={
 'select-show':'sell',seat:'sell','expire-hold':'sell','add-product':'cashier','product-qty':'cashier','promo':'cashier','remove-promo':'cashier',customer:'cashier',guest:'cashier','select-customer':'cashier','checkout':'cashier','payment-method':'cashier','cash-preset':'cashier','settle-payment':'orders','payment-status':'orders','query-payment':'orders','retry-payment':'orders','cancel-order':'orders','print-order':'orders','checkin':'scan','demo-scan':'scan','scan-sample':'scan','next-scan':'scan','food-ready':'fulfillment','incident':'rooms','print-shift':'shift','next-shift':'shift'
};
function checkPermission(p){if(p==='cashier'?!D.hasCashier():!D.can(p))throw Error('Vai trò hiện tại chưa được cấp quyền cho thao tác này.');}
const actions={
 'toggle-menu':()=>{view.menu=!view.menu;render();},
 'close-modal':closeDialog,
 'modal-confirm':()=>{const f=modalCallback;closeDialog();f?.();},
 'logout':()=>confirmAction('Đăng xuất khỏi quầy?','Ca hiện tại vẫn giữ trạng thái. Nếu đã hoàn tất công việc, hãy kết ca và bàn giao trước.',()=>{S().session=false;S().locked=false;D.save();render();},'Đăng xuất'),
 'lock':()=>{closeDialog();S().locked=true;D.save();render();},
 'sale-day':el=>{view.day=Number(el.dataset.day);render();},
 'clear-show-filters':()=>{Object.assign(view,{query:'',format:'all',room:'all',hour:'all'});render();},
 'select-show':el=>selectShow(el.dataset.id),
 'seat':el=>{D.chooseSeat(el.dataset.seat);render();},
 'expire-hold':()=>{if(!S().draft.holdUntil)throw Error('Chọn ghế trước để thử hết giờ giữ chỗ.');if(S().draft.paymentOrder)throw Error('Đơn đã chuyển thanh toán. Kiểm tra trạng thái ở phần giao dịch.');S().draft.holdUntil=D.now()-1;D.expireHold();render();toast('Đã hết giờ giữ ghế. Vui lòng chọn lại ghế.',true);},
 'food-group':el=>{view.foodGroup=el.dataset.group;render();},
 'add-product':el=>{D.addProduct(el.dataset.id,$('#option-'+el.dataset.id).value);render();toast('Đã thêm sản phẩm vào đơn.');},
 'product-qty':el=>{const p=S().draft.products.find(x=>x.key===el.dataset.key);if(p)D.addProduct(p.id,p.option,Number(el.dataset.delta));render();},
 'clear-cart':()=>{if(S().draft.paymentOrder)throw Error('Xử lý kết quả thanh toán trước khi xóa đơn.');confirmAction('Xóa đơn hiện tại?','Các ghế đang chọn và sản phẩm trong đơn sẽ được bỏ.',()=>{D.clearDraft();render();toast('Đã xóa đơn hiện tại.');},'Xóa đơn');},
 'new-food':()=>{if(S().draft.paymentOrder)throw Error('Xử lý đơn đang chờ thanh toán trước khi tạo đơn mới.');if(S().draft.seats.length||S().draft.products.length)confirmAction('Tạo đơn đồ ăn riêng?','Đơn hiện tại chưa thanh toán sẽ được bỏ.',()=>{D.clearDraft();render();},'Tạo đơn mới');else{D.clearDraft();render();}},
 'new-sale':()=>{if(S().draft.paymentOrder)throw Error('Kiểm tra kết quả đơn đang thanh toán trước.');if(S().draft.seats.length||S().draft.products.length)confirmAction('Bắt đầu đơn mới?','Đơn nháp hiện tại sẽ được bỏ.',()=>{D.clearDraft();go(D.can('sell')?'sell':'food');},'Bắt đầu đơn mới');else go(D.can('sell')?'sell':'food');},
 'customer':()=>{if(S().draft.paymentOrder)throw Error('Không thể sửa khách của đơn đang thanh toán.');customerDialog();},
 'guest':()=>{S().draft.customer=null;S().draft.promo='';D.save();closeDialog();render();toast('Đã chọn khách vãng lai.');},
 'select-customer':()=>{S().draft.customer={id:'TV0088',name:'Trần Hoàng Linh',phone:'0918765432'};D.save();closeDialog();render();toast('Đã xác nhận thành viên Trần Hoàng Linh.');},
 'promo':()=>{D.promo($('#promo-input').value);render();toast('Đã áp dụng ưu đãi LUMI10.');},
 'remove-promo':()=>{S().draft.promo='';D.save();render();},
 'checkout':()=>{D.requireOpen();if(D.expireHold()){render();throw Error('Ghế đã hết giờ giữ. Vui lòng chọn lại.');}view.received='';go('checkout');},
 'payment-method':el=>{view.paymentMethod=el.dataset.method;render();},
 'cash-preset':el=>{view.received=el.dataset.value;$('#cash-received').value=view.received;updateChange();},
 'payment-status':el=>paymentDialog(el.dataset.id),
 'query-payment':el=>{D.requireOpen();paymentDialog(el.dataset.id,true);},
 'settle-payment':el=>{const result=$('#payment-result').value,id=el.dataset.id;const o=D.order(id);if(result==='unknown'&&o.payment==='unknown'){closeDialog();toast('Kết quả vẫn chưa rõ. Không thu lại; tiếp tục bàn giao theo dõi.',true);return;}D.settle(id,result);closeDialog();go(result==='success'?'receipt/'+id:'orders/'+id);render();toast(result==='success'?'Đã nhận phản hồi thành công. Có thể xuất chứng từ.':result==='unknown'?'Kết quả chưa rõ. Tra cứu giao dịch trước khi thu lại.':paymentName[result]+'. Hãy kiểm tra hướng xử lý.',result!=='success');},
 'retry-payment':el=>{const o=D.retry(el.dataset.id);paymentDialog(o.id);render();},
 'cancel-order':el=>{const o=D.order(el.dataset.id);D.requireOpen();if(!o||!['pending','failed'].includes(o.payment)||o.status==='cancelled')throw Error('Đơn không đủ điều kiện hủy. Cần xác định thanh toán trước.');confirmAction('Hủy đơn '+o.id+'?','Ghế trong đơn chưa thanh toán sẽ được giải phóng. Thao tác được ghi nhận vào lịch sử.',()=>{o.status='cancelled';o.payment='cancelled';const t=S().transactions.filter(t=>t.orderId===o.id).at(-1);if(t&&t.status!=='success')t.status='expired';if(S().draft.paymentOrder===o.id)D.clearDraft();D.audit('Hủy đơn chưa thanh toán',o);D.save();render();toast('Đã hủy đơn chưa thanh toán.');},'Hủy đơn');},
 'print-order':el=>printOrder(el.dataset.id,el.dataset.kind),
 'demo-scan':()=>{view.scanResult=D.inspectTicket('VE-1001-1');render();toast('Đã mô phỏng quét VE-1001-1. Chưa tự xác nhận vào rạp.');},
 'scan-sample':el=>{view.scanResult=D.inspectTicket(el.dataset.code);render();},
 'checkin':el=>{const t=D.checkIn(el.dataset.code);view.scanResult={...D.inspectTicket(t.id),status:'checked',label:'Đã xác nhận vào rạp',message:`${t.people} người · ${D.stamp(t.checkedAt)} · ${t.checkedBy}.`};render();toast('Đã ghi nhận soát vé '+t.id);},
 'next-scan':()=>{view.scanResult=null;render();},
 'fulfill-status':el=>{view.foodStatus=el.dataset.status;render();},
 'food-ready':el=>{D.requireOpen();const o=D.order(el.dataset.id);if(!o||o.payment!=='paid'||o.foodStatus!=='waiting')throw Error('Đơn không đủ điều kiện chuẩn bị.');o.foodStatus='ready';D.audit('Đã chuẩn bị xong sản phẩm',o);D.save();render();toast('Đơn đã sẵn sàng giao.');},
 'incident':el=>{const sh=el.dataset.id?D.show(el.dataset.id):null;dialog('Báo sự cố vận hành',`<form data-form="incident"><label>Phòng chiếu<select name="roomId">${D.roomDefs.map(r=>`<option value="${r.id}" ${sh?.roomId===r.id?'selected':''}>${r.name} · ${r.type}</option>`).join('')}</select></label><label>Suất liên quan<select name="showId"><option value="">Không gắn suất cụ thể</option>${S().shows.filter(s=>dateShort(s.start)===dateShort(D.now())).map(s=>`<option value="${s.id}" ${sh?.id===s.id?'selected':''}>${D.room(s.roomId).name} · ${D.stamp(s.start)} · ${D.movie(s.movieId).title}</option>`).join('')}</select></label><label>Mức độ<select name="level"><option>Thông thường</option><option>Cần xử lý sớm</option><option>Khẩn cấp</option></select></label><label>Nội dung<textarea name="content" rows="4" required minlength="10" maxlength="500" placeholder="Mô tả sự cố và ảnh hưởng đến khách…"></textarea></label><p class="micro">Báo cáo được lưu cục bộ trong demo. Sự cố khẩn cấp cần liên hệ trực tiếp trưởng ca.</p><button type="submit" class="btn primary full">Ghi nhận sự cố</button></form>`);},
 'print-shift':printShift,
 'next-shift':()=>{if(S().shift.status!=='closed')throw Error('Kết ca hiện tại trước.');S().shiftHistory=S().shiftHistory||[];S().shiftHistory.push(JSON.parse(JSON.stringify(S().shift)));S().shift={id:'CA-'+(++S().seq),status:'pending',opening:0,start:null,end:null,note:'',handover:'',counted:null};D.save();render();},
 'demo-pending-shift':()=>{if(S().shift.status!=='open')throw Error('Tình huống chỉ áp dụng từ ca mẫu đang mở.');confirmAction('Thử tình huống chưa nhận ca?','Ca mẫu sẽ được chuyển thành ca trước. Một ca mới chưa nhận sẽ được tạo để kiểm tra quy trình nhận ca.',()=>{if(S().draft.paymentOrder)throw Error('Xử lý thanh toán trước khi đổi tình huống.');D.clearDraft();S().shiftHistory=S().shiftHistory||[];S().shiftHistory.push({...S().shift,status:'closed',end:D.now(),report:D.stats(),note:'Chuyển ca trong tình huống mô phỏng'});S().shift={id:'CA-'+(++S().seq),status:'pending',opening:0,start:null,end:null,note:'',handover:'',counted:null};D.save();go('shift');render();},'Tạo ca chưa nhận');},
 'reset-demo':()=>confirmAction('Khôi phục dữ liệu mẫu?','Toàn bộ ca, đơn mới, check-in, lịch sử và giao nhận bạn đã thử sẽ bị xóa. Dữ liệu mẫu ban đầu sẽ được tạo lại.',()=>{D.reset();view.scanResult=null;closeDialog();go('dashboard');render();toast('Đã khôi phục dữ liệu mẫu.');},'Khôi phục')
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if((!S().session||S().locked)&&a!=='close-modal')return;try{if(actionPermissions[a])checkPermission(actionPermissions[a]);actions[a]?.(el);}catch(err){toast(err.message,true);}});
document.addEventListener('submit',e=>{const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();const v=new FormData(f),kind=f.dataset.form;if((!S().session||S().locked)&&kind!=='login')return;try{
 if(kind==='login'){S().session=true;S().locked=false;D.save();render();toast('Chào Minh Anh. Đây là phiên làm việc mô phỏng.');}
 if(kind==='open-shift'){checkPermission('shift');if(S().shift.status!=='pending')throw Error('Ca đã được nhận.');const opening=D.hasCashier()?Number(v.get('opening')):0;if(!Number.isFinite(opening)||opening<0)throw Error('Tiền đầu ca không hợp lệ.');S().shift={...S().shift,status:'open',start:D.now(),opening,cashier:D.hasCashier()};D.audit('Nhận ca '+S().shift.id);D.save();go('dashboard');render();toast('Đã nhận ca. Quầy sẵn sàng làm việc.');}
 if(kind==='payment'){checkPermission('cashier');const received=Number(v.get('received')||0),o=D.createPayment(view.paymentMethod,received);if(view.paymentMethod==='cash'){D.settle(o.id,'success');go('receipt/'+o.id);render();toast('Đã ghi nhận thanh toán tiền mặt.');}else{go('orders/'+o.id);render();paymentDialog(o.id);}}
 if(kind==='customer'){checkPermission('cashier');const q=String(v.get('query')).replace(/\s/g,'').toUpperCase();$('#customer-results').innerHTML=['TV0088','0918765432'].includes(q)?`<div class="member-result"><span class="avatar">HL</span><div><strong>Trần Hoàng Linh</strong><span>TV0088 · 091 ••• 432</span><small>Thành viên Lumi · Đang hoạt động</small></div>${btn('Chọn đúng khách','select-customer','primary small')}</div>`:'<div class="notice warning">Không tìm thấy thành viên. Kiểm tra mã hoặc tiếp tục bán cho khách vãng lai.</div>';}
 if(kind==='scan'){checkPermission('scan');view.scanResult=D.inspectTicket(String(v.get('code')));render();}
 if(kind==='deliver'){checkPermission('fulfillment');const quantities=Object.fromEntries(v);const id=f.dataset.id;confirmAction('Xác nhận giao sản phẩm?',`Kiểm tra số lượng thực giao cho đơn <strong>${id}</strong>. Chỉ xác nhận sau khi đã bàn giao đúng món cho khách.`,()=>{D.deliver(id,quantities,quantities.deliveryVersion);render();toast('Đã ghi nhận số lượng giao.');},'Đã giao · Xác nhận');}
 if(kind==='incident'){checkPermission('rooms');D.requireOpen();const sh=v.get('showId')?D.show(v.get('showId')):null;if(sh&&sh.roomId!==v.get('roomId'))throw Error('Suất không thuộc phòng đã chọn. Chọn lại phòng hoặc suất.');if(!String(v.get('content')).trim())throw Error('Vui lòng nhập nội dung sự cố.');S().incidents.push({at:D.now(),actor:S().staff.name,roomId:v.get('roomId'),showId:v.get('showId'),level:v.get('level'),content:String(v.get('content')).trim()});D.audit('Báo sự cố '+D.room(v.get('roomId')).name);D.save();closeDialog();render();toast('Đã lưu báo cáo sự cố minh họa.');}
 if(kind==='close-shift'){checkPermission('shift');const counted=Number(v.get('counted')),note=String(v.get('note')||''),handover=String(v.get('handover')||'');const st=D.stats();if(S().shift.cashier&&counted!==st.expected&&!note.trim())throw Error('Có chênh lệch tiền mặt. Nhập giải thích trước khi kết ca.');confirmAction('Kết thúc ca làm việc?',`Ca <strong>${S().shift.id}</strong> sẽ ngừng nhận giao dịch mới. ${S().shift.cashier?'Tiền thực đếm: <strong>'+D.money(counted)+'</strong>.':''}`,()=>{D.closeShift(counted,note,handover);render();toast('Đã kết ca và tạo biên bản bàn giao.');},'Xác nhận kết ca');}
}catch(err){toast(err.message,true);}});
function renderWithFocus(el){const id=el.id,focus=el===document.activeElement,start=el.selectionStart,end=el.selectionEnd;render();if(focus&&id){const next=$('#'+id);next?.focus();if(next&&start!==null&&next.type!=='number')try{next.setSelectionRange(start,end);}catch(_){}}}
function updateChange(){const total=D.draftTotals().total,n=Number($('#cash-received')?.value||0);const el=$('#change-amount');if(el)el.textContent=n>=total?D.money(n-total):'Còn thiếu '+D.money(total-n);const hint=$('#cash-error');if(hint){hint.textContent=n>=total?'Đã đủ tiền. Kiểm tra tiền thừa trước khi xác nhận.':'Số khách đưa chưa đủ. Nhập lại số tiền đã nhận.';hint.className='field-hint '+(n>=total?'positive':'negative');}}
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.filter){view[el.dataset.filter]=el.value;renderWithFocus(el);}if(el.id==='cash-received'){view.received=el.value;updateChange();}if(el.id==='counted-cash')$('#cash-difference').textContent=el.value===''?'—':D.money(Number(el.value)-D.stats().expected);});
document.addEventListener('change',e=>{const el=e.target;try{if(el.id==='role-switch'){if(S().draft.paymentOrder)throw Error('Đơn đang thanh toán. Xử lý kết quả trước khi chuyển vai trò.');S().role=el.value;if(!D.can('sell')&&S().draft.seats.length){D.clearDraft();toast('Đã bỏ đơn nháp vé vì vai trò mới không có quyền bán vé.');}D.save();view.scanResult=null;closeDialog();go('dashboard');render();toast('Đang thử vai trò: '+D.roles[S().role].name);}if(el.dataset.filter){view[el.dataset.filter]=el.value;renderWithFocus(el);}if(el.dataset.seatType){checkPermission('sell');D.requireOpen();if(S().draft.paymentOrder)throw Error('Không thể sửa đơn đang thanh toán.');const sh=D.show(S().draft.showId),l=S().draft.seats.find(x=>x.seat===el.dataset.seatType),seat=D.seats(sh).find(x=>x.id===l.seat);if(!D.availableTypes(sh,seat).includes(el.value))throw Error('Loại vé không được hỗ trợ.');l.type=el.value;l.price=D.fare(sh,seat,l.type);D.save();render();}}catch(err){toast(err.message,true);render();}});
window.addEventListener('hashchange',()=>{view.menu=false;closeDialog();render();window.scrollTo(0,0);if(route.page!=='scan')$('#main h1')?.focus({preventScroll:true});});
window.addEventListener('storage',e=>{if(e.key===D.KEY)toast('Có thay đổi dữ liệu từ tab khác. Tải lại trang trước khi tiếp tục. Demo không đồng bộ giữ ghế.',true);});
document.addEventListener('keydown',e=>{if(!S().session||S().locked)return;if(e.altKey&&e.key.toLowerCase()==='l'){e.preventDefault();actions.lock();return;}if($('#modal').open)return;const keyRoutes={F2:'sell',F3:'food',F4:'orders',F6:'scan'};if(keyRoutes[e.key]&&D.can(keyRoutes[e.key])){e.preventDefault();go(keyRoutes[e.key]);}if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#main input[type="search"], #movie-search, #order-search, #food-search, #fulfill-search, #scan-code')?.focus();}});
setInterval(()=>{if(!S().session||S().locked)return;const clock=$('#live-clock');if(clock)clock.textContent=D.stamp(D.now());const hold=$('#hold-countdown');if(hold)hold.textContent=holdText();if(D.expireHold()){render();toast('Hết 5 phút giữ ghế. Đã bỏ ghế, sản phẩm vẫn giữ trong đơn. Chọn lại ghế để tiếp tục.',true);}},1000);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeDialog();});
if(!location.hash)history.replaceState(null,'','#/dashboard');
D.expireHold();render();
})();
